export const Route = createFileRoute("/admin")({
  beforeLoad: async ({ location }) => {
    const session = await getAdminSession();
    if (!session && location.pathname !== "/admin/login") {
      throw redirect({ to: "/admin/login" });
    }
  },
  component: AdminRouteLayout,
});

function AdminRouteLayout() {
  const location = useLocation();
  const [session, setSession] = useState<AdminSession | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    void getAdminSession().then((currentSession) => {
      if (!active) return;
      setSession(currentSession);
      setLoading(false);
    });
    return () => {
      active = false;
    };
  }, []);

  if (location.pathname === "/admin/login") return <Outlet />;

  if (loading) {
    return <main className="flex min-h-screen items-center justify-center bg-background text-sm text-muted-foreground">Carregando painel...</main>;
  }

  if (!session) return null;

  return <AdminDashboard session={session} />;
}

function AdminDashboard({ session }: { session: AdminSession }) {
  const navigate = useNavigate();
  const [section, setSection] = useState("Visão geral");
  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>({
    "Visão geral": true,
    Catálogo: true,
    Pedidos: true,
    "Site / Aparência": true,
  });
  const [productArea, setProductArea] = useState<"Produtos" | "Categorias" | "Imagens" | "Variantes" | "Preços" | "Promoções">("Produtos");
  const [inventoryArea, setInventoryArea] = useState<"Estoque" | "Movimentações" | "Reservas" | "Alertas">("Estoque");
  const [appearanceArea, setAppearanceArea] = useState("Home");
  const [alertOrderId, setAlertOrderId] = useState<string | null>(null);
  const [mobileSidebarOpen, setMobileSidebarOpen] = useState(false);

  const sectionDescription: Record<string, string> = {
    "Visão geral": "Acompanhe vendas, pedidos, envios e devoluções em um único lugar.",
    Alertas: "Priorize problemas reais de estoque, reservas e pagamentos.",
    Produtos: "Gerencie o catálogo sem misturar dados operacionais.",
    Estoque: "Controle variantes, movimentações, reservas e limites de alerta.",
    Pedidos: "Consulte pedidos, clientes, pagamentos e status de atendimento.",
    "Site / Aparência": "Edite a experiência publicada na Home e na loja.",
  };

  const sectionTitle = section === "Site / Aparência" ? `Site e Aparência · ${appearanceArea}` : section;
  const breadcrumb = section === "Site / Aparência" ? ["Admin", "Site e Aparência", appearanceArea] : ["Admin", section];
  const headerDescription = sectionDescription[section] || "Administre esta área com segurança a partir dos dados reais da loja.";

  function handleSectionChange(nextSection: string) {
    setSection(nextSection);
    setMobileSidebarOpen(false);
    if (nextSection === "Produtos") setProductArea("Produtos");
    if (nextSection === "Site / Aparência") setAppearanceArea("Home");
  }

  function toggleGroup(group: string) {
    setOpenGroups((current) => ({ ...current, [group]: !current[group] }));
  }

  async function handleSignOut() {
    await signOutAdmin();
    await navigate({ to: "/admin/login", replace: true });
  }

  const navigationGroups = [
    { label: "Visão geral", icon: LayoutDashboard, items: [{ label: "Visão geral", icon: LayoutDashboard }, { label: "Alertas", icon: AlertTriangle }] },
    { label: "Catálogo", icon: Boxes, items: [{ label: "Produtos", icon: Package }, { label: "Estoque", icon: Boxes }] },
    { label: "Pedidos", icon: ShoppingCart, items: [{ label: "Pedidos", icon: ClipboardList }, { label: "Envios e Rastreamento", icon: Truck }, { label: "Devoluções", icon: ShieldCheck }, { label: "Financeiro", icon: CircleDollarSign }] },
    { label: "Clientes", icon: Users, items: [{ label: "Clientes", icon: Users }] },
    { label: "Fornecedores", icon: Store, items: [{ label: "Fornecedores", icon: Store }] },
    { label: "Site e Aparência", icon: Palette, items: [{ label: "Home", icon: Eye }, { label: "Banners", icon: Image }, { label: "Textos", icon: FileText }, { label: "Seções", icon: LayoutDashboard }, { label: "Imagens", icon: Image }, { label: "Vídeos", icon: Video }, { label: "Informações da loja", icon: Store }, { label: "Rodapé", icon: FileText }, { label: "Redes sociais", icon: Users }, { label: "Políticas", icon: ShieldCheck }, { label: "Cores e tema", icon: Palette }] },
    { label: "Configurações", icon: Settings, items: [{ label: "Análises", icon: BarChart3 }, { label: "Configurações", icon: Cog }] },
  ];

  const appearanceNavigation: Record<string, string> = { Home: "Home", Banners: "Banners", Textos: "Textos", Seções: "Seções", Imagens: "Imagens", Vídeos: "Vídeos", "Informações da loja": "Informações da loja", Rodapé: "Rodapé", "Redes sociais": "Redes sociais", Políticas: "Políticas", "Cores e tema": "Cores e tema" };

  return <div className="admin-shell min-h-screen bg-slate-100 text-slate-900">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-72 flex-col bg-slate-950 text-slate-300 transition-transform duration-200 md:translate-x-0 ${mobileSidebarOpen ? "translate-x-0" : "-translate-x-full"}`} aria-label="Navegação administrativa">
      <div className="flex h-20 items-center border-b border-slate-800 px-6"><Link to="/admin" className="text-sm font-semibold tracking-[0.18em] text-white">LEH_CLOSETT <span className="text-cyan-400">ADMIN</span></Link></div>
      <div className="flex-1 overflow-y-auto px-4 py-6"><p className="mb-4 px-3 text-[11px] font-semibold uppercase tracking-[0.22em] text-slate-500">Central de controle</p><nav className="space-y-3">
        {navigationGroups.map((group) => { const GroupIcon = group.icon; return <section key={group.label}><button type="button" onClick={() => toggleGroup(group.label)} aria-expanded={openGroups[group.label] ?? false} className="flex w-full items-center justify-between rounded-lg px-3 py-2 text-left text-[11px] font-semibold uppercase tracking-wider text-slate-500 hover:text-white"><span className="flex items-center gap-2"><GroupIcon size={14} />{group.label}</span>{openGroups[group.label] ? <ChevronDown size={14} /> : <ChevronRight size={14} />}</button>{openGroups[group.label] && <div className="mt-1 space-y-1">{group.items.map((item) => { const ItemIcon = item.icon; const active = section === item.label || (section === "Site / Aparência" && group.label === "Site e Aparência" && appearanceArea === item.label); return <button key={item.label} type="button" onClick={() => { if (group.label === "Site e Aparência") { setSection("Site / Aparência"); setAppearanceArea(appearanceNavigation[item.label] ?? "Home"); setMobileSidebarOpen(false); } else handleSectionChange(item.label); }} className={`flex w-full items-center gap-3 rounded-lg border-l-2 px-3 py-2 text-left text-sm transition ${active ? "border-cyan-400 bg-slate-800 text-white" : "border-transparent text-slate-400 hover:bg-slate-900 hover:text-white"}`}><ItemIcon size={16} />{item.label}</button>; })}</div>}</section>; })}
      </nav></div><div className="border-t border-slate-800 p-4"><p className="truncate px-2 text-xs text-slate-500">{session.email}</p><button type="button" onClick={handleSignOut} className="mt-3 w-full rounded-lg border border-slate-700 px-3 py-2 text-sm text-slate-300 transition hover:border-cyan-400 hover:text-white">Sair do painel</button></div>
    </aside>
    {mobileSidebarOpen && <button type="button" aria-label="Fechar menu" onClick={() => setMobileSidebarOpen(false)} className="fixed inset-0 z-30 bg-slate-950/60 md:hidden" />}
    <div className="min-h-screen md:pl-72">
      <header className="sticky top-0 z-20 border-b border-slate-200 bg-white/95 backdrop-blur"><div className="flex min-h-20 flex-wrap items-center justify-between gap-4 px-5 py-4 md:px-10"><div className="flex items-center gap-4"><button type="button" aria-label="Abrir menu" onClick={() => setMobileSidebarOpen(true)} className="rounded-lg border border-slate-200 p-2 text-slate-600 hover:border-cyan-500 hover:text-cyan-600 md:hidden"><Menu size={20} /></button><div><p className="text-xs font-semibold uppercase tracking-[0.2em] text-cyan-600">Administração</p><p className="text-sm text-slate-500">Operação LEH_CLOSETT</p></div></div><div className="flex items-center gap-2 sm:gap-3"><label className="relative hidden md:block"><span className="sr-only">Buscar no Admin</span><Search size={16} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" /><input disabled aria-label="Busca do Admin indisponível" placeholder="Buscar produtos, pedidos, clientes..." className="h-10 w-64 cursor-not-allowed rounded-lg border border-slate-200 bg-slate-50 pl-9 pr-3 text-sm text-slate-500 opacity-80" title="A busca global ainda não está disponível" /></label><button type="button" aria-label="Notificações" className="rounded-lg border border-slate-200 p-2 text-slate-500 hover:border-cyan-500 hover:text-cyan-600"><Bell size={18} /></button><div className="hidden border-l border-slate-200 pl-3 text-right sm:block"><p className="max-w-40 truncate text-sm font-medium text-slate-800">{session.email}</p><p className="text-xs text-slate-500">Administrador</p></div><button type="button" onClick={() => void handleSignOut()} aria-label="Sair do painel" className="rounded-lg border border-slate-200 p-2 text-slate-500 hover:border-red-300 hover:text-red-600"><LogOut size={18} /></button></div></div></header>
      <main key={section} className="min-w-0 px-5 py-8 md:px-10 md:py-10"><div className="mb-8 border-b border-slate-200 pb-6"><nav aria-label="Breadcrumb" className="mb-3 flex flex-wrap items-center gap-2 text-xs text-slate-400">{breadcrumb.map((item, index) => <span key={`${item}-${index}`} className={index === breadcrumb.length - 1 ? "font-medium text-cyan-600" : ""}>{index > 0 && <span className="mr-2 text-slate-300">/</span>}{item}</span>)}</nav><div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-end"><div><h1 className="text-3xl font-semibold tracking-tight text-slate-950 md:text-4xl">{sectionTitle}</h1><p className="mt-2 max-w-2xl text-sm leading-relaxed text-slate-500">{headerDescription}</p></div></div></div>{section === "Visão geral" ? <OverviewDashboard onNavigate={(target) => { if (target === "banners") { setSection("Site / Aparência"); setAppearanceArea("Banners"); } else if (target === "home") { setSection("Site / Aparência"); setAppearanceArea("Home"); } else if (target === "estoque") { setSection("Estoque"); setInventoryArea("Estoque"); } else if (target === "produtos") { setSection("Produtos"); setProductArea("Produtos"); } else { setSection("Pedidos"); } }} /> : section === "Site / Aparência" ? <AppearanceArea area={appearanceArea} onAreaChange={setAppearanceArea} /> : section === "Produtos" ? <ProductsArea area={productArea} onAreaChange={setProductArea} /> : section === "Estoque" ? <InventoryArea area={inventoryArea} onAreaChange={setInventoryArea} /> : section === "Alertas" ? <AdminAlertsPage onOpenArea={(area) => { setSection("Estoque"); setInventoryArea(area); }} onOpenOrder={(orderId) => { setSection("Pedidos"); setAlertOrderId(orderId); }} /> : section === "Pedidos" ? <OrdersManagerList initialOrderId={alertOrderId} /> : section === "Envios e Rastreamento" ? <ShipmentsManager /> : section === "Fornecedores" ? <SuppliersManager /> : <section className="mt-8 rounded-xl border border-slate-200 bg-white p-8 shadow-sm"><p className="text-slate-500">Selecione uma função no menu para visualizar e gerenciar esta área.</p></section>}</main>
    </div>
  </div>;
}

function OverviewDashboardLegacy() {
  const [period, setPeriod] = useState<"day" | "week" | "month">("week");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [now, setNow] = useState(new Date());
  const [orders, setOrders] = useState<any[]>([]);
  const [shipments, setShipments] = useState<any[]>([]);
  const [refunds, setRefunds] = useState<any[]>([]);

  useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 60000); return () => window.clearInterval(timer); }, []);
  useEffect(() => { void (async () => {
    if (!supabase) { setError("Supabase não está configurado."); setLoading(false); return; }
    try {
      setLoading(true); setError("");
      const [orderResult, shipmentResult, refundResult] = await Promise.all([
        supabase.from("orders").select("id,total,created_at,status,payment_status,order_items(*)"),
        supabase.from("shipments").select("id,status,order_id"),
        supabase.from("refunds").select("amount,status,created_at")
      ]);
      if (orderResult.error) throw orderResult.error;
      if (shipmentResult.error) throw shipmentResult.error;
      if (refundResult.error) throw refundResult.error;
      setOrders(orderResult.data ?? []); setShipments(shipmentResult.data ?? []); setRefunds(refundResult.data ?? []);
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os indicadores."); }
    finally { setLoading(false); }
  })(); }, []);

  const start = new Date();
  if (period === "day") start.setHours(0, 0, 0, 0);
  if (period === "week") { start.setDate(start.getDate() - 6); start.setHours(0, 0, 0, 0); }
  if (period === "month") { start.setDate(1); start.setHours(0, 0, 0, 0); }
  const paid = (order: any) => ["paid", "approved", "pago", "approved_payment"].includes(String(order.payment_status || "").toLowerCase());
  const periodOrders = orders.filter((order) => paid(order) && new Date(order.created_at) >= start);
  const sales = periodOrders.reduce((sum, order) => sum + Number(order.total || 0), 0);
  const totalSales = orders.filter(paid).reduce((sum, order) => sum + Number(order.total || 0), 0);
  const pending = orders.filter((order) => ["preparing", "processing", "paid", "pago"].includes(String(order.status || "").toLowerCase())).length;
  const inTransit = shipments.filter((shipment) => ["shipped", "in_transit", "em_transit", "em trânsito"].includes(String(shipment.status || "").toLowerCase())).length;
  const delivered = shipments.filter((shipment) => ["delivered", "entregue"].includes(String(shipment.status || "").toLowerCase())).length;
  const refundsTotal = refunds.filter((refund) => !refund.status || !["cancelled", "rejected"].includes(String(refund.status).toLowerCase())).reduce((sum, refund) => sum + Number(refund.amount || 0), 0);
  const buckets = period === "day" ? 6 : period === "week" ? 7 : 5;
  const chart = Array.from({ length: buckets }, (_, index) => { const date = new Date(start); if (period === "day") date.setHours(index * 4); else if (period === "week") date.setDate(start.getDate() + index); else date.setDate(1 + index * Math.max(1, Math.floor((new Date().getDate() - 1) / Math.max(1, buckets - 1)))); const next = new Date(date); if (period === "day") next.setHours(date.getHours() + 4); else if (period === "week") next.setDate(date.getDate() + 1); else next.setDate(date.getDate() + 7); return { label: period === "day" ? `${date.getHours()}h` : date.toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" }), value: periodOrders.filter((order) => { const created = new Date(order.created_at); return created >= date && created < next; }).reduce((sum, order) => sum + Number(order.total || 0), 0) }; });
  const max = Math.max(...chart.map((item) => item.value), 1);
  const card = (label: string, value: string) => <article className="rounded-xl border border-border bg-card p-5"><p className="text-xs uppercase tracking-wider text-muted-foreground">{label}</p><p className="mt-3 text-2xl font-semibold tabular-nums">{loading ? "—" : value}</p></article>;
  return <div className="mt-8 space-y-6">{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-muted-foreground">Atualizado em {now.toLocaleString("pt-BR")}</p><div className="flex rounded-lg border border-border p-1">{(["day", "week", "month"] as const).map((item) => <button key={item} type="button" onClick={() => setPeriod(item)} className={`rounded-md px-3 py-1.5 text-sm ${period === item ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"}`}>{item === "day" ? "Dia" : item === "week" ? "Semana" : "Mês"}</button>)}</div></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{card("Vendas no período", `R$ ${sales.toFixed(2)}`)}{card("Vendas totais", `R$ ${totalSales.toFixed(2)}`)}{card("Aguardando postagem", String(pending))}{card("Em trânsito", String(inTransit))}{card("Entregues", String(delivered))}{card("Total de devoluções", `R$ ${refundsTotal.toFixed(2)}`)}</div><section className="rounded-xl border border-border bg-card p-5"><div className="flex items-center justify-between"><div><h2 className="text-lg font-semibold">Vendas</h2><p className="text-sm text-muted-foreground">Pedidos pagos no período selecionado</p></div><strong className="text-xl">R$ {sales.toFixed(2)}</strong></div><div className="mt-6 flex h-48 items-end gap-2 border-b border-border">{chart.map((item) => <div key={item.label} className="flex flex-1 flex-col items-center gap-2"><div title={`R$ ${item.value.toFixed(2)}`} className="w-full rounded-t-md bg-primary transition-all" style={{ height: `${Math.max(item.value / max * 100, item.value ? 4 : 1)}%` }} /><span className="text-[11px] text-muted-foreground">{item.label}</span></div>)}</div></section></div>;
}

function OverviewDashboard({ onNavigate }: { onNavigate: (target: "produtos" | "pedidos" | "banners" | "home" | "estoque") => void }) {
  const [orders, setOrders] = useState<any[]>([]);
  const [products, setProducts] = useState<AdminProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => { void (async () => {
    try {
      setLoading(true);
      const [orderRows, productRows] = await Promise.all([listAdminOrders(), listAdminProducts()]);
      setOrders(orderRows); setProducts(productRows);
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar a visão geral."); }
    finally { setLoading(false); }
  })(); }, []);

  const today = new Date(); today.setHours(0, 0, 0, 0);
  const todayOrders = orders.filter((order) => new Date(order.created_at).getTime() >= today.getTime());
  const paid = (order: any) => ["paid", "approved", "pago", "approved_payment", "confirmed"].includes(String(order.payment_status || "").toLowerCase());
  const todaySales = todayOrders.filter(paid).reduce((sum, order) => sum + Number(order.total || 0), 0);
  const customers = new Set(orders.map((order) => order.user_id || order.customer_email || order.shipping_address?.email).filter(Boolean));
  const lowStock = products.flatMap((product) => product.product_variants).filter((variant) => variant.stock_quantity <= 5).length;
  const money = (value: number) => `R$ ${value.toFixed(2).replace(".", ",")}`;
  const card = (label: string, value: string) => <article className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><p className="text-xs font-semibold uppercase tracking-wider text-slate-500">{label}</p><p className="mt-3 text-2xl font-semibold text-slate-950">{loading ? "—" : value}</p></article>;
  const actions: Array<[string, string, "produtos" | "pedidos" | "banners" | "home" | "estoque"]> = [["Adicionar produto", "Cadastre um novo item no catálogo", "produtos"], ["Novo pedido", "Acesse os pedidos reais", "pedidos"], ["Gerenciar banners", "Atualize os destaques da Home", "banners"], ["Editar Home", "Administre textos e seções", "home"], ["Ver estoque", "Confira variantes e alertas", "estoque"]];
  return <div className="mt-8 space-y-6">
    {error && <p className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</p>}
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{card("Pedidos hoje", String(todayOrders.length))}{card("Vendas hoje", money(todaySales))}{card("Clientes ativos", String(customers.size))}{card("Estoque baixo", String(lowStock))}</div>
    <div className="grid gap-6 lg:grid-cols-[1.35fr_0.65fr]">
      <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="text-lg font-semibold text-slate-950">Vendas recentes</h2><p className="text-sm text-slate-500">Valores dos pedidos pagos nos últimos registros.</p></div><span className="text-xs text-slate-500">Dados reais</span></div><div className="mt-6 flex h-40 items-end gap-2 border-b border-slate-200">{[...orders].filter(paid).slice(0, 7).reverse().map((order) => { const max = Math.max(...orders.filter(paid).map((item) => Number(item.total || 0)), 1); return <div key={order.id} className="flex flex-1 flex-col items-center gap-2"><div title={money(Number(order.total || 0))} className="w-full rounded-t bg-cyan-600" style={{ height: `${Math.max(Number(order.total || 0) / max * 100, 5)}%` }} /><span className="text-[10px] text-slate-400">{new Date(order.created_at).toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" })}</span></div>; })}</div></section>
      <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><h2 className="text-lg font-semibold text-slate-950">Ações rápidas</h2><div className="mt-4 space-y-2">{actions.map(([label, description, target]) => <button key={label} type="button" onClick={() => onNavigate(target)} className="flex w-full items-start justify-between rounded-lg border border-slate-200 p-3 text-left transition hover:border-cyan-500 hover:bg-cyan-50"><span><span className="block text-sm font-medium text-slate-900">{label}</span><span className="text-xs text-slate-500">{description}</span></span><span className="text-cyan-600">→</span></button>)}</div></section>
    </div>
    <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="text-lg font-semibold text-slate-950">Pedidos recentes</h2><p className="text-sm text-slate-500">Acompanhe os últimos pedidos registrados.</p></div><button type="button" onClick={() => onNavigate("pedidos")} className="text-sm font-medium text-cyan-700 hover:underline">Ver todos</button></div><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[620px] text-left text-sm"><thead className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500"><tr><th className="p-3">Pedido</th><th className="p-3">Cliente</th><th className="p-3">Status</th><th className="p-3">Valor</th></tr></thead><tbody>{loading ? <tr><td colSpan={4} className="p-6 text-center text-slate-500">Carregando pedidos reais...</td></tr> : orders.slice(0, 5).map((order) => <tr key={order.id} className="border-b border-slate-100 last:border-0"><td className="p-3 font-medium">{order.order_number || order.id}</td><td className="p-3 text-slate-600">{order.customer_name || order.customer_email || order.shipping_address?.full_name || "Cliente não identificado"}</td><td className="p-3 text-slate-600">{order.status || "—"}</td><td className="p-3">{money(Number(order.total || 0))}</td></tr>)}{!loading && orders.length === 0 && <tr><td colSpan={4} className="p-6 text-center text-slate-500">Nenhum pedido real encontrado.</td></tr>}</tbody></table></div></section>
  </div>;
}

function AppearanceArea({ area, onAreaChange }: { area: string; onAreaChange: (area: string) => void }) {
  const areas = ["Home", "Banners", "Textos", "Seções", "Imagens", "Vídeos", "Informações da loja", "Rodapé", "Redes sociais", "Políticas", "Cores e tema"];
  const cards: Array<{ name: string; description: string; icon: typeof Eye }> = [
    { name: "Home", description: "Organize a apresentação e o conteúdo principal da loja.", icon: Eye },
    { name: "Banners", description: "Controle as imagens e chamadas exibidas na Home.", icon: Image },
    { name: "Textos", description: "Edite títulos, frases e chamadas da experiência da loja.", icon: FileText },
    { name: "Seções", description: "Configure os blocos de conteúdo publicados na Home.", icon: LayoutDashboard },
    { name: "Imagens", description: "Gerencie as imagens já utilizadas pelo site.", icon: Image },
    { name: "Vídeos", description: "Administre os vídeos vinculados ao catálogo e à loja.", icon: Video },
    { name: "Informações da loja", description: "Atualize apresentação, contatos e dados públicos.", icon: Store },
    { name: "Rodapé", description: "Edite as informações exibidas no rodapé do site.", icon: FileText },
    { name: "Redes sociais", description: "Mantenha os links sociais da loja atualizados.", icon: Users },
    { name: "Políticas", description: "Acesse e organize as políticas apresentadas ao cliente.", icon: ShieldCheck },
    { name: "Cores e tema", description: "Controle a identidade visual publicada na loja.", icon: Palette },
  ];
  const renderArea = () => area === "Banners" ? <BannersEditor /> : area === "Textos" ? <TextAppearanceEditor /> : area === "Seções" ? <HomeSectionsEditor /> : area === "Imagens" ? <HomeImagesEditor /> : area === "Informações da loja" ? <StorePresentationEditor /> : area === "Rodapé" ? <StorePresentationEditor mode="footer" /> : area === "Redes sociais" ? <StorePresentationEditor mode="social" /> : <section className="rounded-xl border border-border bg-card p-8"><h2 className="text-xl font-semibold">{area}</h2><p className="mt-2 text-sm text-muted-foreground">Esta área será exibida aqui quando houver conteúdo persistido disponível.</p></section>;
  return <div className="mt-8 space-y-6">
    <nav aria-label="Navegação de Site e Aparência" className="flex flex-wrap gap-2 border-b border-border pb-px">{areas.map((item) => <button key={item} type="button" onClick={() => onAreaChange(item)} aria-current={area === item ? "page" : undefined} className={`rounded-md border-b-2 px-3 py-2 text-left text-sm transition ${area === item ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:bg-muted hover:text-foreground"}`}>{item}</button>)}</nav>
    {area === "Home" ? <section aria-labelledby="appearance-center-title" className="space-y-5"><div><h2 id="appearance-center-title" className="text-xl font-semibold">Central de controle</h2><p className="mt-1 max-w-2xl text-sm text-muted-foreground">Escolha uma área para editar somente o conteúdo correspondente.</p></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{cards.map(({ name, description, icon: Icon }) => <article key={name} className="flex min-h-48 flex-col rounded-xl border border-border bg-card p-5 shadow-sm transition hover:border-primary/50 hover:shadow-md"><div className="flex items-center justify-between gap-3"><span className="rounded-lg bg-muted p-2 text-primary"><Icon size={19} aria-hidden="true" /></span><span className="text-xs text-muted-foreground">Área administrativa</span></div><h3 className="mt-5 text-base font-semibold">{name}</h3><p className="mt-2 flex-1 text-sm leading-relaxed text-muted-foreground">{description}</p><button type="button" onClick={() => onAreaChange(name)} className="mt-5 self-start rounded-lg bg-primary px-3 py-2 text-sm font-medium text-primary-foreground transition hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">Gerenciar</button></article>)}</div></section> : renderArea()}
  </div>;
}

type HomeSection = { id: string; title: string; type: "Categoria" | "Destaques" | "Mais vendidos" | "Produtos" | "Personalizada"; active: boolean; sort_order: number; category_id?: string; product_ids?: string[]; product_sort?: "recent" | "price_desc" | "price_asc" }; 

function HomeSectionsEditor() {
  const blank: Omit<HomeSection, "id"> = { title: "", type: "Destaques", active: true, sort_order: 0, category_id: "", product_ids: [], product_sort: "recent" }; 
  const [rows, setRows] = useState<HomeSection[]>([]); const [form, setForm] = useState(blank); const [editing, setEditing] = useState<string | undefined>(); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
  const [categories, setCategories] = useState<AdminCategory[]>([]); const [products, setProducts] = useState<AdminProduct[]>([]);
  async function load() { if (!supabase) { setMessage("Supabase não está configurado."); setLoading(false); return; } const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) setMessage(error.message); const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; const value = Array.isArray(appearance.sections) ? appearance.sections : []; setRows(value.map((item, index) => ({ id: String((item as Record<string, unknown>).id ?? crypto.randomUUID()), title: String((item as Record<string, unknown>).title ?? ""), type: ((item as Record<string, unknown>).type ?? "Destaques") as HomeSection["type"], active: Boolean((item as Record<string, unknown>).active ?? true), sort_order: Number((item as Record<string, unknown>).sort_order ?? index), category_id: String((item as Record<string, unknown>).category_id ?? ""), product_ids: Array.isArray((item as Record<string, unknown>).product_ids) ? (item as Record<string, unknown>).product_ids as string[] : [], product_sort: ((item as Record<string, unknown>).product_sort ?? "recent") as HomeSection["product_sort"] })).sort((a, b) => a.sort_order - b.sort_order)); setLoading(false); }
  useEffect(() => { void load(); void (async () => { try { const [categoryRows, productRows] = await Promise.all([listAdminCategories(), listAdminProducts()]); setCategories(categoryRows.filter((item) => item.active)); setProducts(productRows.filter((item) => item.active)); } catch { setMessage("Não foi possível carregar categorias e produtos."); } })(); }, []);
  async function persist(next: HomeSection[]) { if (!supabase) return; const current = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (current.error) throw current.error; const appearance = current.data?.appearance && typeof current.data.appearance === "object" ? current.data.appearance as Record<string, unknown> : {}; const result = await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, sections: next } }); if (result.error) throw result.error; setRows(next); }
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!form.title.trim()) return; try { setSaving(true); setMessage(""); const next = editing ? rows.map((row) => row.id === editing ? { id: editing, ...form } : row) : [...rows, { id: crypto.randomUUID(), ...form, sort_order: rows.length }]; await persist(next); setForm(blank); setEditing(undefined); setMessage("Seções salvas no Supabase."); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível salvar."); } finally { setSaving(false); } }
  async function remove(id: string) { if (!window.confirm("Excluir esta seção da Home?")) return; try { await persist(rows.filter((row) => row.id !== id).map((row, index) => ({ ...row, sort_order: index }))); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível excluir."); } }
  async function move(id: string, direction: -1 | 1) { const index = rows.findIndex((row) => row.id === id); const target = index + direction; if (target < 0 || target >= rows.length) return; const next = [...rows]; [next[index], next[target]] = [next[target], next[index]]; try { await persist(next.map((row, order) => ({ ...row, sort_order: order }))); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível reordenar."); } }
  return <div className="space-y-6"><form onSubmit={submit} className="grid gap-4 rounded-xl border border-border bg-card p-5 md:grid-cols-2"><label className="text-sm">Título personalizado<input required value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Tipo<select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value as HomeSection["type"], category_id: "", product_ids: [] })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3">{["Categoria", "Destaques", "Mais vendidos", "Produtos", "Personalizada"].map((type) => <option key={type}>{type}</option>)}</select></label>{form.type === "Categoria" && <label className="text-sm">Categoria<select value={form.category_id} onChange={(e) => setForm({ ...form, category_id: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="">Selecione uma categoria</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label>}{(form.type === "Destaques" || form.type === "Produtos" || form.type === "Personalizada") && <div className="space-y-3 md:col-span-2"><div><p className="text-sm">Produtos selecionados <span className="text-muted-foreground">({form.product_ids.length}{form.type === "Destaques" ? "/10" : ""})</span></p><p className="mt-1 text-xs text-muted-foreground">A Home exibirá os produtos exatamente nesta ordem.</p>{form.type === "Personalizada" && <p className="mt-1 text-xs text-primary">Divisão personalizada da Home.</p>}</div><div className="space-y-2">{form.product_ids.length === 0 ? <p className="rounded-lg border border-dashed border-border p-4 text-sm text-muted-foreground">Nenhum produto selecionado.</p> : form.product_ids.map((productId, index) => { const product = products.find((item) => item.id === productId); return product ? <div key={product.id} className="flex items-center justify-between gap-3 rounded-lg border border-border px-3 py-2"><span className="truncate text-sm">{index + 1}. {product.name}</span><div className="flex shrink-0 gap-2 text-xs"><button type="button" disabled={index === 0} onClick={() => { const ids = [...form.product_ids]; [ids[index - 1], ids[index]] = [ids[index], ids[index - 1]]; setForm({ ...form, product_ids: ids }); }} className="text-primary disabled:opacity-40">Subir</button><button type="button" disabled={index === form.product_ids.length - 1} onClick={() => { const ids = [...form.product_ids]; [ids[index], ids[index + 1]] = [ids[index + 1], ids[index]]; setForm({ ...form, product_ids: ids }); }} className="text-primary disabled:opacity-40">Descer</button><button type="button" onClick={() => setForm({ ...form, product_ids: form.product_ids.filter((id) => id !== product.id) })} className="text-destructive">Remover</button></div></div> : null; })}</div><label className="block text-sm">Adicionar produto<select value="" disabled={form.type === "Destaques" && form.product_ids.length >= 10} onChange={(e) => { const id = e.target.value; if (id && !form.product_ids.includes(id) && (form.type !== "Destaques" || form.product_ids.length < 10)) setForm({ ...form, product_ids: [...form.product_ids, id] }); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="">{form.type === "Destaques" && form.product_ids.length >= 10 ? "Limite de 10 produtos atingido" : "Selecione um produto"}</option>{products.filter((product) => !form.product_ids.includes(product.id)).map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select></label>{form.type === "Produtos" && <label className="block text-sm">Ordenação<select value={form.product_sort ?? "recent"} onChange={(e) => setForm({ ...form, product_sort: e.target.value as HomeSection["product_sort"] })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="recent">Mais recentes</option><option value="price_desc">Maior preço</option><option value="price_asc">Menor preço</option></select></label>}</div>}<label className="flex items-center gap-2 pb-2 text-sm"><input type="checkbox" checked={form.active} onChange={(e) => setForm({ ...form, active: e.target.checked })} />Ativa</label><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : editing ? "Atualizar" : "Criar seção"}</button></form>{message && <p className="rounded-lg border border-border bg-muted p-3 text-sm">{message}</p>}{loading ? <p className="text-sm text-muted-foreground">Carregando seções...</p> : rows.length === 0 ? <p className="rounded-xl border border-border bg-card p-8 text-sm text-muted-foreground">Nenhuma seção administrada. A Home não exibirá blocos de conteúdo.</p> : <div className="space-y-3">{rows.map((row, index) => <article key={row.id} className="flex flex-wrap items-center justify-between gap-4 rounded-xl border border-border bg-card p-4"><div><h3 className="font-medium">{row.title}</h3><p className="text-sm text-muted-foreground">{row.type} · {row.active ? "Ativa" : "Inativa"} · {row.product_ids?.length ?? 0} produtos · posição {index + 1}</p></div><div className="flex gap-3 text-sm"><button type="button" disabled={index === 0} onClick={() => void move(row.id, -1)} className="text-primary disabled:opacity-40">Subir</button><button type="button" disabled={index === rows.length - 1} onClick={() => void move(row.id, 1)} className="text-primary disabled:opacity-40">Descer</button><button type="button" onClick={() => { setEditing(row.id); setForm({ title: row.title, type: row.type, active: row.active, sort_order: row.sort_order, category_id: row.category_id ?? "", product_ids: row.product_ids ?? [], product_sort: row.product_sort ?? "recent" }); }} className="text-primary">Editar</button><button type="button" onClick={() => void remove(row.id)} className="text-destructive">Excluir</button></div></article>)}</div>}</div>;
}

type StorePresentation = { storeName: string; storeDescription: string; instagram: string; linktree: string; whatsapp: string; whatsappFloating: string; footer: string };
type TextAppearance = { title: string; phrase: string; titleFont: string; titleSize: string; titleColor: string; phraseFont: string; phraseSize: string; phraseColor: string; textWidth: string; textFormat: "normal" | "uppercase" | "italic"; heroEyebrow: string; primaryCta: string; primaryCtaUrl: string; secondaryCta: string; secondaryCtaUrl: string; sectionEyebrow: string; shippingHighlight: string; shippingText: string };
const defaultTextAppearance: TextAppearance = { title: "", phrase: "", titleFont: "Playfair Display", titleSize: "clamp(3rem, 8vw, 7rem)", titleColor: "var(--foreground)", phraseFont: "Montserrat", phraseSize: "1rem", phraseColor: "var(--foreground)", textWidth: "32rem", textFormat: "normal", heroEyebrow: "", primaryCta: "", primaryCtaUrl: "", secondaryCta: "", secondaryCtaUrl: "", sectionEyebrow: "", shippingHighlight: "", shippingText: "" };

const defaultStorePresentation: StorePresentation = { storeName: "LEH_CLOSETT GLOW", storeDescription: "Moda para iluminar quem você é.", instagram: "", linktree: "", whatsapp: "", whatsappFloating: "", footer: "© 2025 LEH_CLOSETT GLOW. Todos os direitos reservados." };

function StorePresentationEditor({ mode = "all" }: { mode?: "all" | "footer" | "social" }) {
  const [form, setForm] = useState<StorePresentation>(defaultStorePresentation); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
  useEffect(() => { void (async () => { if (!supabase) { setMessage("Supabase não está configurado."); setLoading(false); return; } const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) setMessage(error.message); const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; setForm({ ...defaultStorePresentation, ...(appearance.presentation as Partial<StorePresentation> | undefined) }); setLoading(false); })(); }, []);
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!supabase) return; try { setSaving(true); const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) throw error; const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; const result = await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, presentation: form } }); if (result.error) throw result.error; setMessage("Apresentação salva no Supabase."); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível salvar."); } finally { setSaving(false); } }
  const fields: Array<[keyof StorePresentation, string, string]> = mode === "footer" ? [["footer", "Texto do rodapé", ""]] : mode === "social" ? [["instagram", "Instagram", "https://instagram.com/"], ["linktree", "Linktree", "https://linktr.ee/"] , ["whatsapp", "WhatsApp", "https://wa.me/"] , ["whatsappFloating", "Número do botão flutuante", "5511999999999"]] : [["storeName", "Nome da loja", ""], ["storeDescription", "Descrição da loja", ""], ["instagram", "Instagram", "https://instagram.com/"], ["linktree", "Linktree", "https://linktr.ee/"], ["whatsapp", "WhatsApp", "https://wa.me/"], ["whatsappFloating", "Número do botão flutuante", "5511999999999"], ["footer", "Texto do rodapé", ""]];
  return <section className="rounded-xl border border-border bg-card p-5"><h2 className="text-xl font-semibold">Apresentação da loja</h2><p className="mt-1 text-sm text-muted-foreground">Esses dados são salvos na configuração real da loja.</p><form onSubmit={submit} className="mt-5 grid gap-4 md:grid-cols-2">{loading ? <p className="text-sm text-muted-foreground">Carregando configurações...</p> : <>{fields.map(([key, label, placeholder]) => <label key={key} className="text-sm">{label}{key === "storeDescription" || key === "footer" ? <textarea value={form[key]} placeholder={placeholder} onChange={(event) => setForm({ ...form, [key]: event.target.value })} rows={3} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /> : <input value={form[key]} placeholder={placeholder} onChange={(event) => setForm({ ...form, [key]: event.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" />}</label>)}<div className="md:col-span-2"><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : "Salvar apresentação"}</button></div></>}</form>{message && <p className="mt-4 rounded-lg border border-border bg-muted p-3 text-sm">{message}</p>}</section>;
}

function HomeImagesEditor() {
  const [images, setImages] = useState<Array<{ id: string; url: string; label: string; source: string }>>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => { void (async () => {
    try {
      const [banners, products] = await Promise.all([listAdminBanners(), listAdminProducts()]);
      const bannerImages = banners.filter((banner) => banner.image_url).map((banner) => ({ id: `banner-${banner.id}`, url: banner.image_url!, label: banner.title || "Banner da Home", source: "Banners" }));
      const productImages = products.flatMap((product) => product.product_images.map((image) => ({ id: `product-${image.id}`, url: image.image_url, label: product.name, source: "Produtos" })));
      setImages([...bannerImages, ...productImages]);
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar as imagens utilizadas pelo site."); }
    finally { setLoading(false); }
  })(); }, []);

  return <section className="rounded-xl border border-border bg-card p-5"><h2 className="text-xl font-semibold">Imagens utilizadas pelo site</h2><p className="mt-1 text-sm text-muted-foreground">Visualização das imagens reais já vinculadas a banners e produtos. O cadastro e a remoção continuam nas áreas de origem para evitar listas paralelas.</p>{error && <p className="mt-4 rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}{loading ? <p className="mt-5 text-sm text-muted-foreground">Carregando imagens...</p> : images.length === 0 ? <p className="mt-5 rounded-lg border border-dashed border-border p-5 text-sm text-muted-foreground">Nenhuma imagem armazenada foi encontrada.</p> : <div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{images.map((image) => <figure key={image.id} className="overflow-hidden rounded-lg border border-border"><img src={image.url} alt={image.label} className="aspect-[4/3] w-full object-cover" /><figcaption className="p-3"><p className="truncate text-sm font-medium">{image.label}</p><p className="text-xs text-muted-foreground">Origem: {image.source}</p></figcaption></figure>)}</div>}</section>;
}

function TextAppearanceEditor() {
  const [form, setForm] = useState<TextAppearance>(defaultTextAppearance);
  const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
  useEffect(() => { void (async () => { if (!supabase) { setMessage("Supabase não está configurado."); setLoading(false); return; } const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) setMessage(error.message); const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; setForm({ ...defaultTextAppearance, ...(appearance.texts as Partial<TextAppearance> | undefined) }); setLoading(false); })(); }, []);
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!supabase) return; try { setSaving(true); setMessage(""); const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) throw error; const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; const result = await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, texts: form } }); if (result.error) throw result.error; setMessage("Configurações salvas no Supabase."); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível salvar."); } finally { setSaving(false); } }
  return <section className="rounded-xl border border-border bg-card p-5"><div className="mb-5"><h2 className="text-xl font-semibold">Textos da Home</h2><p className="mt-1 text-sm text-muted-foreground">Ajuste título e frase do banner. As alterações são aplicadas na Home após salvar.</p></div><form onSubmit={submit} className="grid gap-4 md:grid-cols-2">{loading ? <p className="text-sm text-muted-foreground">Carregando configurações...</p> : <><label className="text-sm">Título do Hero<input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Frase do Hero<textarea value={form.phrase} onChange={(e) => setForm({ ...form, phrase: e.target.value })} rows={3} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /></label><label className="text-sm">Fonte do título<select value={form.titleFont} onChange={(e) => setForm({ ...form, titleFont: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option>Playfair Display</option><option>Montserrat</option><option>Syncopate</option></select></label><label className="text-sm">Tamanho do título<input value={form.titleSize} onChange={(e) => setForm({ ...form, titleSize: e.target.value })} placeholder="Ex.: clamp(3rem, 8vw, 7rem)" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Cor do título<input value={form.titleColor} onChange={(e) => setForm({ ...form, titleColor: e.target.value })} placeholder="Ex.: var(--foreground)" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Fonte da frase<select value={form.phraseFont} onChange={(e) => setForm({ ...form, phraseFont: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option>Montserrat</option><option>Playfair Display</option><option>Syncopate</option></select></label><label className="text-sm">Tamanho da frase<input value={form.phraseSize} onChange={(e) => setForm({ ...form, phraseSize: e.target.value })} placeholder="Ex.: 1rem" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Cor da frase<input value={form.phraseColor} onChange={(e) => setForm({ ...form, phraseColor: e.target.value })} placeholder="Ex.: var(--foreground)" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Largura dos textos<input value={form.textWidth} onChange={(e) => setForm({ ...form, textWidth: e.target.value })} placeholder="Ex.: 32rem" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Formatação<select value={form.textFormat} onChange={(e) => setForm({ ...form, textFormat: e.target.value as TextAppearance["textFormat"] })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="normal">Normal</option><option value="uppercase">Maiúsculas</option><option value="italic">Itálico</option></select></label><label className="text-sm">Eyebrow da Home<input value={form.heroEyebrow} onChange={(e) => setForm({ ...form, heroEyebrow: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">CTA principal<input value={form.primaryCta} onChange={(e) => setForm({ ...form, primaryCta: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Link do CTA principal<input value={form.primaryCtaUrl} onChange={(e) => setForm({ ...form, primaryCtaUrl: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">CTA secundário<input value={form.secondaryCta} onChange={(e) => setForm({ ...form, secondaryCta: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Link do CTA secundário<input value={form.secondaryCtaUrl} onChange={(e) => setForm({ ...form, secondaryCtaUrl: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Eyebrow das seções<input value={form.sectionEyebrow} onChange={(e) => setForm({ ...form, sectionEyebrow: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Destaque do aviso de frete<input value={form.shippingHighlight} onChange={(e) => setForm({ ...form, shippingHighlight: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Texto do aviso de frete<input value={form.shippingText} onChange={(e) => setForm({ ...form, shippingText: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><div className="md:col-span-2"><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : "Salvar configurações"}</button></div></>}</form>{message && <p className="mt-4 rounded-lg border border-border bg-muted p-3 text-sm">{message}</p>}</section>;
}

function BannersEditor() {
  const empty = { image_url: "", title: "", text: "", link_url: "", sort_order: 0, active: true };
  const [rows, setRows] = useState<Banner[]>([]); const [form, setForm] = useState(empty); const [editing, setEditing] = useState<string | undefined>(); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState(""); const [rotationSeconds, setRotationSeconds] = useState(3); const [savingRotation, setSavingRotation] = useState(false);
  async function load() { try { setLoading(true); const [banners, rotation] = await Promise.all([listAdminBanners(), getBannerRotationSeconds()]); setRows(banners); setRotationSeconds(rotation); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os banners."); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []);
  async function saveRotation() { const value = Number.isFinite(rotationSeconds) ? Math.max(1, Math.round(rotationSeconds)) : 3; setRotationSeconds(value); try { setSavingRotation(true); setError(""); await saveBannerRotationSeconds(value); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível salvar o intervalo."); } finally { setSavingRotation(false); } }
  async function submit(event: React.FormEvent) { event.preventDefault(); try { setSaving(true); await saveAdminBanner({ id: editing, ...form, sort_order: Number(form.sort_order) }); setForm(empty); setEditing(undefined); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível salvar o banner."); } finally { setSaving(false); } }
  async function remove(id: string) { if (!window.confirm("Excluir este banner?")) return; try { await deleteAdminBanner(id); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível excluir o banner."); } }
  return <div className="space-y-6"><section className="rounded-xl border border-border bg-card p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><h2 className="text-xl font-semibold">Personalização da Home</h2><p className="mt-1 max-w-2xl text-sm text-muted-foreground">Edite os textos publicados em cada banner. A Home usa a ordem e a frase de cada registro ativo.</p></div><label className="flex items-center gap-2 text-xs text-primary">Rotação (segundos)<input type="number" min="1" step="1" value={rotationSeconds} onChange={(event) => setRotationSeconds(Number(event.target.value))} onBlur={() => void saveRotation()} onKeyDown={(event) => { if (event.key === "Enter") void saveRotation(); }} className="h-8 w-20 rounded-lg border border-primary/40 bg-background px-2 text-foreground" />{savingRotation ? "Salvando..." : ""}</label></div><p className="mt-4 text-xs text-muted-foreground">O intervalo padrão é de 3 segundos. Altere o valor acima para definir o tempo de rotação automática na Home.</p></section><form onSubmit={submit} className="grid gap-4 rounded-xl border border-border bg-card p-5 md:grid-cols-2"><label className="text-sm">Título principal<input aria-label="Título principal do banner" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Imagem (URL)<input required value={form.image_url} onChange={(e) => setForm({ ...form, image_url: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm md:col-span-2">Frase usada neste banner<textarea aria-label="Frase usada neste banner" rows={3} value={form.text} onChange={(e) => setForm({ ...form, text: e.target.value })} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /></label><label className="text-sm">Link da ação<input value={form.link_url} onChange={(e) => setForm({ ...form, link_url: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Ordem de exibição<input type="number" min="0" value={form.sort_order} onChange={(e) => setForm({ ...form, sort_order: Number(e.target.value) })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={form.active} onChange={(e) => setForm({ ...form, active: e.target.checked })} />Banner ativo</label><div className="md:col-span-2"><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : editing ? "Atualizar banner" : "Adicionar banner"}</button></div></form>{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="grid gap-4 md:grid-cols-2">{loading ? <p className="text-sm text-muted-foreground">Carregando banners...</p> : rows.length === 0 ? <p className="rounded-xl border border-border bg-card p-8 text-sm text-muted-foreground">Nenhum banner cadastrado.</p> : rows.map((banner) => <article key={banner.id} className="overflow-hidden rounded-xl border border-border bg-card"><img src={banner.image_url || ""} alt={banner.title || "Banner da Home"} className="aspect-[16/7] w-full object-cover" /><div className="space-y-3 p-4"><div className="flex items-center justify-between gap-3"><h3 className="font-medium">{banner.title || "Sem título"}</h3><span className="text-xs text-muted-foreground">{banner.active ? "Ativo" : "Inativo"}</span></div><p className="text-sm text-muted-foreground">{banner.text || "Sem frase definida"}</p><div className="flex gap-4 text-sm"><button type="button" onClick={() => void (async () => { try { await saveAdminBanner({ id: banner.id, image_url: banner.image_url, title: banner.title, text: banner.text, link_url: banner.link_url, sort_order: banner.sort_order, active: !banner.active }); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível alterar o status do banner."); } })()} className="text-primary hover:underline">{banner.active ? "Desativar" : "Ativar"}</button><button type="button" onClick={() => { setEditing(banner.id); setForm({ image_url: banner.image_url || "", title: banner.title || "", text: banner.text || "", link_url: banner.link_url || "", sort_order: banner.sort_order, active: banner.active }); }} className="text-primary hover:underline">Editar</button><button type="button" onClick={() => void remove(banner.id)} className="text-destructive hover:underline">Excluir</button></div></div></article>)}</div></div>;
}

function ProductsArea({ area, onAreaChange }: { area: "Produtos" | "Categorias" | "Imagens" | "Variantes" | "Preços" | "Promoções"; onAreaChange: (area: "Produtos" | "Categorias" | "Imagens" | "Variantes" | "Preços" | "Promoções") => void }) {
  const areas = ["Produtos", "Categorias", "Variantes", "Imagens", "Preços", "Promoções"] as const;

  function renderArea() {
    switch (area) {
      case "Categorias": return <CategoriesManager />;
      case "Variantes": return <ProductVariantsManager />;
      case "Imagens": return <ProductImagesManager />;
      case "Preços": return <ProductPricesManager />;
      case "Promoções": return <ProductPromotionsManager />;
      case "Produtos": return <AdminProductsManager />;
    }
  }

  return <div className="mt-8 space-y-6">
    <nav aria-label="Navegação de Produtos" className="flex flex-wrap gap-2 border-b border-border">
      {areas.map((item) => <button key={item} type="button" onClick={() => onAreaChange(item)} aria-current={area === item ? "page" : undefined} className={`border-b-2 px-3 py-2 text-sm transition ${area === item ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground"}`}>{item}</button>)}
    </nav>
    <div key={area}>{renderArea()}</div>
  </div>;
}

function AdminProductsManager() {
  const emptyForm = { name: "", slug: "", description: "", price: "", category_id: "", active: true, featured: false, published: true, sku: "", stock_quantity: "0", image: "", images: "", video: "", colors: "", sizes: "", variantStock: {} as Record<string, string> };
  const [products, setProducts] = useState<AdminProduct[]>([]);
  const [categories, setCategories] = useState<AdminCategory[]>([]);
  const [form, setForm] = useState(emptyForm);
  const [editingId, setEditingId] = useState<string | undefined>();
  const [showForm, setShowForm] = useState(false);
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("all");
  const [status, setStatus] = useState("all");
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [imageFiles, setImageFiles] = useState<File[]>([]);
  const [error, setError] = useState("");
  const pageSize = 10;
  const fabricColors = ["Preto", "Branco", "Off-white", "Bege", "Marrom", "Caramelo", "Cinza", "Azul-marinho", "Azul", "Verde", "Rosa", "Vermelho"];
  const sizeOptions = ["PP", "P", "M", "G", "GG", "XG"];

  async function load() {
    try { setLoading(true); setError(""); const [productRows, categoryRows] = await Promise.all([listAdminProducts(), listAdminCategories()]); setProducts(productRows); setCategories(categoryRows); }
    catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os produtos."); }
    finally { setLoading(false); }
  }
  useEffect(() => { void load(); }, []);
  const filtered = products.filter((product) => {
    const matchesQuery = `${product.name} ${product.slug}`.toLowerCase().includes(query.toLowerCase());
    return matchesQuery && (category === "all" || product.category_id === category) && (status === "all" || (status === "active" ? product.active : !product.active));
  });
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const visible = filtered.slice((page - 1) * pageSize, page * pageSize);
  const primaryImage = (product: AdminProduct) => product.product_images.find((image) => image.is_primary) ?? product.product_images[0];
  const categoryName = (id: string | null) => categories.find((item) => item.id === id)?.name || "Sem categoria";
  function startNew() { setEditingId(undefined); setForm(emptyForm); setShowForm(true); }
  function edit(product: AdminProduct) { const image = primaryImage(product); setEditingId(product.id); setShowForm(true); setForm({ ...emptyForm, name: product.name, slug: product.slug, description: product.description || "", price: String(product.price), category_id: product.category_id || "", active: product.active, featured: product.featured, published: product.published, video: product.video_url || "", sku: product.product_variants[0]?.sku || "", stock_quantity: String(product.product_variants[0]?.stock_quantity ?? 0), image: image?.image_url || "", images: product.product_images.map((item) => item.image_url).join("\n"), colors: [...new Set(product.product_variants.map((item) => item.color).filter(Boolean))].join(", "), sizes: [...new Set(product.product_variants.map((item) => item.size).filter(Boolean))].join(", "), variantStock: Object.fromEntries(product.product_variants.map((item) => [`${item.color ?? ""}::${item.size ?? ""}`, String(item.stock_quantity)])) }); }
  async function submit(event: React.FormEvent) { event.preventDefault(); const sizes = form.sizes.split(",").map((item) => item.trim()).filter(Boolean); const colors = form.colors.split(",").map((item) => item.trim()).filter(Boolean); const quantitiesMissing = sizes.some((size) => (colors.length ? colors : [""]).some((color) => form.variantStock[`${color}::${size}`] === undefined || form.variantStock[`${color}::${size}`] === "")); if (!form.name.trim() || !form.slug.trim() || !sizes.length || quantitiesMissing) { setError(!sizes.length ? "Selecione pelo menos um tamanho." : quantitiesMissing ? "Informe o estoque de todas as combinações selecionadas." : "Preencha nome e slug."); return; } try { setSaving(true); setError(""); const savedProductId = await saveAdminProduct({ id: editingId, name: form.name.trim(), slug: form.slug.trim(), description: form.description, price: Number(form.price), category_id: form.category_id || null, active: form.active, featured: form.featured, published: form.published, video_url: form.video.trim() || null, sizes, colors, sku: form.sku.trim(), stock_quantity: Number(form.stock_quantity), images: [...new Set(`${form.image}\n${form.images}`.split("\n").map((item) => item.trim()).filter(Boolean))], primaryImage: 0, variantStock: Object.fromEntries(Object.entries(form.variantStock).map(([key, value]) => [key, Number(value)])) }); for (const [index, file] of imageFiles.entries()) await uploadAdminProductImage(savedProductId, file, form.name.trim(), form.images.split("\n").filter(Boolean).length + index, false); if (videoFile) { const duration = await new Promise<number>((resolve, reject) => { const video = document.createElement("video"); video.preload = "metadata"; video.onloadedmetadata = () => resolve(video.duration); video.onerror = () => reject(new Error("Não foi possível validar o vídeo.")); video.src = URL.createObjectURL(videoFile); }); if (duration > 120) throw new Error("O vídeo deve ter no máximo 2 minutos."); await uploadAdminProductVideo(savedProductId, videoFile); } setVideoFile(null); setImageFiles([]); setForm(emptyForm); setEditingId(undefined); setShowForm(false); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível salvar o produto."); } finally { setSaving(false); } }
  async function remove(product: AdminProduct) { if (!window.confirm(`Excluir o produto ${product.name}? Esta ação não pode ser desfeita.`)) return; try { setError(""); await deleteAdminProduct(product.id); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível excluir o produto."); } }
  return <div className="space-y-6">
    <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><p className="text-sm text-muted-foreground">Catálogo real da loja</p><h2 className="mt-1 text-2xl font-semibold">Produtos</h2></div><button type="button" onClick={startNew} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground transition hover:opacity-90">Adicionar produto</button></div>
    {showForm ? <form onSubmit={submit} className="grid gap-4 rounded-xl border border-primary/40 bg-card p-5 md:grid-cols-2"><h3 className="text-xl font-semibold md:col-span-2">{editingId ? "Editar produto" : "Novo produto"}</h3><label className="text-sm">Nome<input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Slug<input required value={form.slug} onChange={(e) => setForm({ ...form, slug: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Preço<input required type="number" min="0" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Categoria<select value={form.category_id} onChange={(e) => setForm({ ...form, category_id: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="">Sem categoria</option>{categories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="text-sm">Estoque<input type="number" min="0" value={form.stock_quantity} onChange={(e) => setForm({ ...form, stock_quantity: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">SKU<input value={form.sku} onChange={(e) => setForm({ ...form, sku: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm md:col-span-2">Imagem principal (URL)<input value={form.image} onChange={(e) => setForm({ ...form, image: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><p className="text-xs text-muted-foreground md:col-span-2">As imagens são gravadas em product_images e as combinações em product_variants.</p><label className="text-sm md:col-span-2">Imagens adicionais (uma URL por linha)<textarea value={form.images} onChange={(e) => setForm({ ...form, images: e.target.value })} rows={3} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /><span className="mt-2 block text-xs text-muted-foreground">Ou selecione várias imagens da galeria do dispositivo.</span><input type="file" accept="image/*" multiple onChange={(e) => setImageFiles(Array.from(e.target.files ?? []))} className="mt-2 w-full text-sm" />{imageFiles.length > 0 && <span className="mt-1 block text-xs text-primary">{imageFiles.length} imagem(ns) selecionada(s).</span>}</label><label className="text-sm md:col-span-2">Vídeo do produto (URL)<textarea value={form.video} onChange={(e) => setForm({ ...form, video: e.target.value })} rows={2} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /><span className="mt-2 block text-xs text-muted-foreground">Ou envie um vídeo de até 2 minutos pelo dispositivo.</span><input type="file" accept="video/*" onChange={(e) => setVideoFile(e.target.files?.[0] ?? null)} className="mt-2 w-full text-sm" /></label><fieldset className="space-y-2 text-sm"><legend>Cor</legend><div className="flex flex-wrap gap-2">{fabricColors.map((color) => { const selected = form.colors.split(",").map((item) => item.trim()).filter(Boolean).includes(color); return <button type="button" key={color} onClick={() => setForm({ ...form, colors: selected ? form.colors.split(",").map((item) => item.trim()).filter((item) => item !== color).join(", ") : [...form.colors.split(",").map((item) => item.trim()).filter(Boolean), color].join(", ") })} className={`rounded-full border px-3 py-1.5 text-xs ${selected ? "border-primary bg-primary text-primary-foreground" : "border-border"}`}>{color}</button>; })}</div><input aria-label="Cor manual" placeholder="Outra cor manual" value={form.colors.split(",").find((color) => !fabricColors.includes(color.trim()))?.trim() ?? ""} onChange={(e) => { const selected = form.colors.split(",").map((item) => item.trim()).filter((item) => fabricColors.includes(item)); setForm({ ...form, colors: [...selected, e.target.value.trim()].filter(Boolean).join(", ") }); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></fieldset><fieldset className="space-y-2 text-sm"><legend>Tamanhos</legend><div className="flex flex-wrap gap-2">{sizeOptions.map((size) => { const selected = form.sizes.split(",").map((item) => item.trim()).includes(size); return <button type="button" key={size} onClick={() => setForm({ ...form, sizes: selected ? form.sizes.split(",").map((item) => item.trim()).filter((item) => item !== size).join(", ") : [...form.sizes.split(",").map((item) => item.trim()).filter(Boolean), size].join(", ") })} className={`rounded-lg border px-4 py-2 text-sm ${selected ? "border-primary bg-primary text-primary-foreground" : "border-border"}`}>{size}</button>; })}</div></fieldset><div className="grid gap-3 md:col-span-2 md:grid-cols-3">{form.sizes.split(",").map((size) => size.trim()).filter(Boolean).flatMap((size) => { const colors = form.colors.split(",").map((color) => color.trim()).filter(Boolean); return (colors.length ? colors : [""]).map((color) => { const key = `${color}::${size}`; return <label key={key} className="text-sm">Estoque · {color || "Única"} / {size}<input type="number" min="0" value={form.variantStock[key] ?? form.stock_quantity} onChange={(event) => setForm({ ...form, variantStock: { ...form.variantStock, [key]: event.target.value } })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label>; }); })}</div><label className="text-sm md:col-span-2">Descrição<textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} rows={3} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /></label><div className="flex flex-wrap gap-4 text-sm md:col-span-2"><label className="flex items-center gap-2"><input type="checkbox" checked={form.active} onChange={(e) => setForm({ ...form, active: e.target.checked })} />Ativo</label><label className="flex items-center gap-2"><input type="checkbox" checked={form.published} onChange={(e) => setForm({ ...form, published: e.target.checked })} />Publicado</label><label className="flex items-center gap-2"><input type="checkbox" checked={form.featured} onChange={(e) => setForm({ ...form, featured: e.target.checked })} />Destaque</label></div><div className="flex gap-3 md:col-span-2"><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : editingId ? "Atualizar produto" : "Salvar produto"}</button><button type="button" onClick={() => { setShowForm(false); setEditingId(undefined); setForm(emptyForm); }} className="rounded-lg border border-border px-4 py-2 text-sm">Cancelar</button></div></form> : null}
    <div className="grid gap-3 rounded-xl border border-border bg-card p-4 md:grid-cols-[1fr_12rem_10rem]"><label className="text-sm font-medium">Buscar produto<input aria-label="Buscar produto" value={query} onChange={(e) => { setQuery(e.target.value); setPage(1); }} placeholder="Nome ou slug" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm font-medium">Categoria<select value={category} onChange={(e) => { setCategory(e.target.value); setPage(1); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todas</option>{categories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="text-sm font-medium">Status<select value={status} onChange={(e) => { setStatus(e.target.value); setPage(1); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option><option value="active">Ativos</option><option value="inactive">Inativos</option></select></label></div>
    {error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}
    <div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[820px] text-left text-sm"><thead className="border-b border-border text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Produto</th><th className="p-4">Categoria</th><th className="p-4">Preço</th><th className="p-4">Estoque</th><th className="p-4">Status</th><th className="p-4">Ações</th></tr></thead><tbody>{loading ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Carregando produtos...</td></tr> : visible.length === 0 ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Nenhum produto encontrado.</td></tr> : visible.map((product) => { const image = primaryImage(product); const stock = product.product_variants.reduce((sum, variant) => sum + variant.stock_quantity, 0); return <tr key={product.id} tabIndex={0} role="button" onClick={() => edit(product)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") edit(product); }} className="cursor-pointer border-b border-border transition hover:bg-muted/50 focus-visible:bg-muted/50 last:border-0"><td className="p-4"><div className="flex items-center gap-3"><div className="h-14 w-12 overflow-hidden rounded-lg border border-border bg-muted">{image ? <img src={image.image_url} alt={image.alt_text || product.name} className="h-full w-full object-cover" /> : null}</div><div><p className="font-medium">{product.name}</p><p className="text-xs text-muted-foreground">{product.slug}</p></div></div></td><td className="p-4 text-muted-foreground">{categoryName(product.category_id)}</td><td className="p-4">R$ {product.price.toFixed(2)}</td><td className="p-4">{stock}</td><td className="p-4">{product.active ? "Ativo" : "Inativo"}</td><td className="p-4"><button type="button" onClick={(event) => { event.stopPropagation(); edit(product); }} className="mr-3 text-primary hover:underline">Editar</button><button type="button" onClick={(event) => { event.stopPropagation(); void remove(product); }} className="text-destructive hover:underline">Excluir</button></td></tr>; })}</tbody></table></div>
    <div className="flex items-center justify-between gap-4 text-sm text-muted-foreground"><span>{filtered.length} produto(s) · Página {page} de {totalPages}</span><div className="flex gap-2"><button type="button" aria-label="Página anterior" disabled={page === 1} onClick={() => setPage((current) => current - 1)} className="rounded-lg border border-border px-3 py-2 text-lg leading-none transition hover:border-primary hover:text-primary disabled:opacity-40">&lt;</button><button type="button" aria-label="Próxima página" disabled={page >= totalPages} onClick={() => setPage((current) => current + 1)} className="rounded-lg border border-border px-3 py-2 text-lg leading-none transition hover:border-primary hover:text-primary disabled:opacity-40">&gt;</button></div></div>
  </div>;
}

function OrdersManager({ initialOrderId }: { initialOrderId?: string | null }) {
  const [orders, setOrders] = useState<any[]>([]);
  const [selected, setSelected] = useState<any | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [savingStatus, setSavingStatus] = useState(false);
  useEffect(() => { void (async () => { try { const rows = await listAdminOrders(); setOrders(rows); if (initialOrderId) setSelected(rows.find((order) => order.id === initialOrderId) ?? null); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os pedidos."); } finally { setLoading(false); } })(); }, [initialOrderId]);
  async function openOrder(id: string) { try { setError(""); const order = await getAdminOrder(id); setSelected(order); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os detalhes."); } }
  async function changeStatus(status: string) { if (!selected || !status) return; try { setSavingStatus(true); await updateAdminOrderStatus(selected.id, status); const refreshed = await getAdminOrder(selected.id); setSelected(refreshed); setOrders((current) => current.map((order) => order.id === refreshed.id ? { ...order, status: refreshed.status } : order)); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível atualizar o status."); } finally { setSavingStatus(false); } }
  const customer = (order: any) => order.shipping_address?.full_name || order.customer_name || order.customer_email || "Cliente não identificado";
  const payment = (order: any) => order.payment_status || order.payment_method || "—";
  const address = (order: any) => { const value = order.shipping_address; if (!value) return "Não informado"; return [value.address, value.cep, value.city, value.state].filter(Boolean).join(" · ") || "Não informado"; };
  const shipment = (order: any) => order.shipments?.[0];
  return <div className="mt-8 space-y-6">{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}{selected && <section className="rounded-xl border border-primary/40 bg-card p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-xs uppercase tracking-[0.2em] text-primary">Detalhes do pedido</p><h2 className="mt-2 text-2xl font-semibold">{selected.order_number || selected.number}</h2></div><button type="button" onClick={() => setSelected(null)} className="text-sm text-muted-foreground hover:text-foreground">Fechar</button></div><div className="mt-5 grid gap-3 text-sm md:grid-cols-2"><p><span className="text-muted-foreground">Cliente:</span> {customer(selected)}</p><p><span className="text-muted-foreground">Endereço:</span> {address(selected)}</p><p><span className="text-muted-foreground">Pagamento:</span> {payment(selected)}</p><p><span className="text-muted-foreground">Total:</span> R$ {Number(selected.total || 0).toFixed(2)}</p><label><span className="text-muted-foreground">Status:</span><select value={selected.status || ""} disabled={savingStatus} onChange={(event) => void changeStatus(event.target.value)} className="ml-2 rounded-lg border border-input bg-background px-2 py-1"><option value="">Selecione</option>{["pending", "preparing", "shipped", "delivered", "cancelled"].map((status) => <option key={status} value={status}>{status}</option>)}</select></label><p><span className="text-muted-foreground">Entrega:</span> {shipment(selected)?.status || "Em preparação"}{shipment(selected)?.tracking_code ? ` · ${shipment(selected).tracking_code}` : ""}</p></div><div className="mt-5 border-t border-border pt-4"><h3 className="font-medium">Itens</h3>{(selected.order_items || []).map((item: any) => <p key={item.id} className="mt-2 text-sm text-muted-foreground">{item.product_name || item.name || "Produto"} · quantidade: {item.quantity} · R$ {Number(item.total || item.unit_price || item.price || 0).toFixed(2)}</p>)}</div></section>}<div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full text-left text-sm"><thead className="border-b border-border text-muted-foreground"><tr><th className="p-4">Número do pedido</th><th className="p-4">Cliente</th><th className="p-4">Data</th><th className="p-4">Status</th><th className="p-4">Pagamento</th><th className="p-4">Total</th><th className="p-4">Ação</th></tr></thead><tbody>{loading ? <tr><td colSpan={7} className="p-8 text-center text-muted-foreground">Carregando pedidos...</td></tr> : orders.length === 0 ? <tr><td colSpan={7} className="p-8 text-center text-muted-foreground">Nenhum pedido encontrado.</td></tr> : orders.map((order) => <tr key={order.id} className="border-b border-border last:border-0"><td className="p-4 font-medium">{order.order_number || order.number || order.id}</td><td className="p-4">{customer(order)}</td><td className="p-4 text-muted-foreground">{order.created_at ? new Date(order.created_at).toLocaleString("pt-BR") : "—"}</td><td className="p-4">{order.status || "—"}</td><td className="p-4">{payment(order)}</td><td className="p-4">R$ {Number(order.total || 0).toFixed(2)}</td><td className="p-4"><button type="button" onClick={() => void openOrder(order.id)} className="text-primary hover:underline">Ver detalhes</button></td></tr>)}</tbody></table></div></div>;
}

function OrderDetails({ order, onClose }: { order: any; onClose: () => void }) {
  const itemImage = (item: any) => item.product?.product_images?.find((image: any) => image.is_primary) ?? item.product?.product_images?.[0];
  const address = order.shipping_address ?? {};
  const payment = order.payments?.[0] ?? order.payment ?? {};
  const shipment = order.shipments?.[0] ?? order.shipment ?? {};
  const subtotal = Number(order.subtotal ?? order.order_items?.reduce((sum: number, item: any) => sum + Number(item.subtotal ?? item.total ?? Number(item.unit_price ?? item.price ?? 0) * Number(item.quantity ?? 0)), 0) ?? 0);
  const freight = Number(order.shipping_total ?? order.shipping ?? order.shipping_cost ?? 0);
  return <section className="space-y-6 rounded-xl border border-primary/40 bg-card p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-xs uppercase tracking-[0.2em] text-primary">Detalhes do pedido</p><h2 className="mt-2 text-2xl font-semibold">{order.order_number || order.id}</h2><p className="text-sm text-muted-foreground">{order.created_at ? new Date(order.created_at).toLocaleString("pt-BR") : "Data não informada"}</p></div><button type="button" onClick={onClose} className="text-sm text-muted-foreground hover:text-foreground">Fechar</button></div>
    <div className="grid gap-4 md:grid-cols-2"><div><h3 className="font-medium">Cliente</h3><p className="mt-2 text-sm">{order.customer_name || address.full_name || "Nome não informado"}</p><p className="text-sm text-muted-foreground">{order.customer_email || address.email || "E-mail não informado"}</p><p className="text-sm text-muted-foreground">{address.phone || order.customer_phone || "Telefone não informado"}</p><p className="mt-2 text-sm text-muted-foreground">{[address.address, address.cep, address.city, address.state].filter(Boolean).join(" · ") || "Endereço não informado"}</p></div><div><h3 className="font-medium">Pagamento</h3><p className="mt-2 text-sm">Status: {payment.status || payment.payment_status || order.payment_status || "Não informado"}</p><p className="text-sm">Valor: R$ {Number(payment.amount ?? payment.transaction_amount ?? order.total ?? 0).toFixed(2).replace(".", ",")}</p><p className="text-sm text-muted-foreground">Referência: {payment.reference || payment.external_reference || payment.preference_id || payment.id || "Não disponível"}</p></div></div>
    <div><h3 className="font-medium">Produtos</h3><div className="mt-3 space-y-3">{(order.order_items ?? []).map((item: any, index: number) => { const image = itemImage(item); const unit = Number(item.unit_price ?? item.price ?? 0); const quantity = Number(item.quantity ?? 0); return <article key={item.id || index} className="flex gap-3 border-b border-border pb-3"><div className="h-16 w-12 shrink-0 overflow-hidden rounded-lg bg-muted">{image ? <img src={image.image_url} alt={image.alt_text || item.product?.name || item.product_name || "Produto"} className="h-full w-full object-cover" /> : null}</div><div className="min-w-0 text-sm"><p className="font-medium">{item.product?.name || item.product_name || item.name || "Produto não identificado"}</p><p className="text-muted-foreground">Cor: {item.variant?.color || item.color || "—"} · Tamanho: {item.variant?.size || item.size || "—"} · SKU: {item.variant?.sku || item.sku || "—"}</p><p className="text-muted-foreground">Quantidade: {quantity} · Unitário: R$ {unit.toFixed(2).replace(".", ",")} · Subtotal: R$ {(Number(item.subtotal ?? item.total ?? unit * quantity)).toFixed(2).replace(".", ",")}</p></div></article>; })}</div></div>
    <div className="grid gap-3 border-t border-border pt-4 text-sm md:grid-cols-3"><p>Subtotal: R$ {subtotal.toFixed(2).replace(".", ",")}</p><p>Frete: R$ {freight.toFixed(2).replace(".", ",")}</p><p className="font-semibold">Total: R$ {Number(order.total ?? subtotal + freight).toFixed(2).replace(".", ",")}</p></div>
    <div className="grid gap-4 md:grid-cols-2"><div><h3 className="font-medium">Entrega</h3><p className="mt-2 text-sm">Status: {shipment.status || order.shipping_status || "Não informado"}</p><p className="text-sm">Transportadora: {shipment.carrier || shipment.service || "Não informada"}</p><p className="text-sm text-muted-foreground">Rastreio: {shipment.tracking_code || shipment.tracking_number || "Não disponível"}</p></div><div><h3 className="font-medium">Linha do tempo</h3><ol className="mt-2 space-y-2 text-sm"><li>Pedido criado · {order.created_at ? new Date(order.created_at).toLocaleString("pt-BR") : "—"}</li><li>Status atual · {order.status || "Não informado"}</li><li>Pagamento · {payment.status || payment.payment_status || order.payment_status || "Não informado"}</li><li>Transporte · {shipment.status || order.shipping_status || "Não informado"}</li></ol></div></div>
  </section>;
}

function ShipmentsManager() {
  const [rows, setRows] = useState<any[]>([]); const [query, setQuery] = useState(""); const [status, setStatus] = useState("all"); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [selectedOrder, setSelectedOrder] = useState<any | null>(null); const [saving, setSaving] = useState(false); const [form, setForm] = useState({ carrier: "", tracking_code: "", tracking_url: "", status: "pending", order_item_ids: [] as string[] });
  useEffect(() => { void (async () => { try { if (!supabase) throw new Error("Supabase não está configurado."); const [ordersResult, paymentsResult, shipmentsResult] = await Promise.all([supabase.from("orders").select("*, order_items(*)").order("created_at", { ascending: false }), supabase.from("payments").select("*"), supabase.from("shipments").select("*").order("created_at", { ascending: false })]); if (ordersResult.error) throw ordersResult.error; if (paymentsResult.error) throw paymentsResult.error; if (shipmentsResult.error) throw shipmentsResult.error; const paid = new Set((paymentsResult.data ?? []).filter((p: any) => ["approved", "confirmed", "paid", "pago", "aprovado", "confirmado"].includes(String(p.status ?? p.payment_status ?? "").toLowerCase())).map((p: any) => String(p.order_id ?? p.external_reference ?? ""))); const byOrder = new Map<string, any[]>(); (shipmentsResult.data ?? []).forEach((s: any) => { const list = byOrder.get(String(s.order_id)) ?? []; list.push(s); byOrder.set(String(s.order_id), list); }); const loaded = (ordersResult.data ?? []).filter((o: any) => paid.has(String(o.id))).flatMap((order: any) => (byOrder.get(String(order.id)) ?? [null]).map((shipment: any) => ({ order, shipment, count: (byOrder.get(String(order.id)) ?? []).length }))); setRows(loaded); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os envios reais."); } finally { setLoading(false); } })(); }, []);
  const label = (row: any) => row.order.shipping_address?.full_name || row.order.customer_name || row.order.customer_email || "Cliente não identificado";
  const text = (row: any) => `${row.order.order_number || row.order.id} ${label(row)} ${row.shipment?.tracking_code || row.shipment?.tracking_number || ""}`.toLowerCase();
  const statuses = [...new Set(rows.map((row) => row.shipment?.status || "Sem rastreio"))];
  const filtered = rows.filter((row) => text(row).includes(query.toLowerCase()) && (status === "all" || (row.shipment?.status || "Sem rastreio") === status));
  async function saveShipment(event: React.FormEvent) { event.preventDefault(); if (!selectedOrder || !supabase) return; try { setSaving(true); const { error: insertError } = await supabase.from("shipments").insert({ order_id: selectedOrder.id, carrier: form.carrier.trim() || null, tracking_code: form.tracking_code.trim() || null, tracking_url: form.tracking_url.trim() || null, status: form.status, order_item_ids: form.order_item_ids }); if (insertError) throw insertError; setSelectedOrder(null); setForm({ carrier: "", tracking_code: "", tracking_url: "", status: "pending", order_item_ids: [] }); window.location.reload(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível cadastrar o envio real."); } finally { setSaving(false); } }
  return <div className="mt-8 space-y-6">{selectedOrder && <form onSubmit={saveShipment} className="space-y-4 rounded-xl border border-primary/40 bg-card p-5"><div className="flex items-center justify-between"><div><p className="text-xs uppercase tracking-wider text-primary">Novo rastreio</p><h2 className="text-xl font-semibold">Pedido {selectedOrder.order_number || selectedOrder.id}</h2></div><button type="button" onClick={() => setSelectedOrder(null)} className="text-sm text-muted-foreground">Fechar</button></div><label className="block text-sm">Transportadora<input required value={form.carrier} onChange={(e) => setForm({ ...form, carrier: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="block text-sm">Código de rastreio<input value={form.tracking_code} onChange={(e) => setForm({ ...form, tracking_code: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="block text-sm">URL de rastreamento<input type="url" value={form.tracking_url} onChange={(e) => setForm({ ...form, tracking_url: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="block text-sm">Status<select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="pending">Pendente</option><option value="in_transit">Em trânsito</option><option value="delivered">Entregue</option></select></label><fieldset><legend className="text-sm">Produtos relacionados</legend><div className="mt-2 space-y-2">{(selectedOrder.order_items ?? []).map((item: any) => <label key={item.id} className="flex items-center gap-2 text-sm"><input type="checkbox" checked={form.order_item_ids.includes(item.id)} onChange={(e) => setForm({ ...form, order_item_ids: e.target.checked ? [...form.order_item_ids, item.id] : form.order_item_ids.filter((id) => id !== item.id) })} />{item.product_name || item.name || "Produto"} · qtd. {item.quantity}</label>)}</div></fieldset><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : "Cadastrar envio"}</button></form>}{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="grid gap-3 rounded-xl border border-border bg-card p-4 md:grid-cols-[1fr_14rem]"><label className="text-sm font-medium">Buscar pedido, cliente ou código<input aria-label="Buscar envio" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Número, nome ou rastreio" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm font-medium">Status<select aria-label="Filtrar envios por status" value={status} onChange={(e) => setStatus(e.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option>{statuses.map((item) => <option key={String(item)}>{String(item)}</option>)}</select></label></div><div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[1050px] text-left text-sm"><thead className="border-b border-border text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Pedido</th><th className="p-4">Cliente</th><th className="p-4">Produtos</th><th className="p-4">Data</th><th className="p-4">Transportadora</th><th className="p-4">Rastreio</th><th className="p-4">Status</th><th className="p-4">Rastreios</th></tr></thead><tbody>{loading ? <tr><td colSpan={8} className="p-8 text-center text-muted-foreground">Carregando envios reais...</td></tr> : filtered.length === 0 ? <tr><td colSpan={8} className="p-8 text-center text-muted-foreground">Nenhum envio encontrado.</td></tr> : filtered.map((row, index) => <tr key={`${row.order.id}-${row.shipment?.id || index}`} className="border-b border-border last:border-0"><td className="p-4 font-medium">{row.order.order_number || row.order.id}</td><td className="p-4">{label(row)}</td><td className="p-4">{(row.order.order_items ?? []).map((item: any) => `${item.product_name || item.name || "Produto"} (${item.quantity || 0})`).join(", ") || "—"}</td><td className="p-4 text-muted-foreground">{new Date(row.shipment?.created_at || row.order.created_at).toLocaleString("pt-BR")}</td><td className="p-4">{row.shipment?.carrier || row.shipment?.service || "—"}</td><td className="p-4">{row.shipment?.tracking_code || row.shipment?.tracking_number || "Ainda não informado"}</td><td className="p-4">{row.shipment?.status || "Sem rastreio"}</td><td className="p-4">{row.count}</td><td className="p-4"><button type="button" onClick={() => { setSelectedOrder(row.order); setForm({ carrier: row.shipment?.carrier || "", tracking_code: "", tracking_url: "", status: "pending", order_item_ids: [] }); }} className="text-primary hover:underline">Adicionar rastreio</button></td></tr>)}</tbody></table></div></div>;
}

function OrdersManagerList({ initialOrderId }: { initialOrderId?: string | null }) {
  const [rows, setRows] = useState<any[]>([]); const [selected, setSelected] = useState<any | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  const [query, setQuery] = useState(""); const [period, setPeriod] = useState("all"); const [orderStatus, setOrderStatus] = useState("all"); const [paymentStatus, setPaymentStatus] = useState("all"); const [shippingStatus, setShippingStatus] = useState("all");
  useEffect(() => { void (async () => { try { if (!supabase) throw new Error("Supabase não está configurado."); const [ordersResult, paymentsResult, shipmentsResult] = await Promise.all([supabase.from("orders").select("*, order_items(*)").order("created_at", { ascending: false }), supabase.from("payments").select("*"), supabase.from("shipments").select("*")]); if (ordersResult.error) throw ordersResult.error; if (paymentsResult.error) throw paymentsResult.error; if (shipmentsResult.error) throw shipmentsResult.error; const payments = new Map((paymentsResult.data ?? []).map((item: any) => [String(item.order_id ?? item.external_reference ?? item.order_id_external ?? ""), item])); const shipments = new Map((shipmentsResult.data ?? []).map((item: any) => [String(item.order_id ?? ""), item])); const loaded = (ordersResult.data ?? []).map((order: any) => ({ ...order, payment: payments.get(String(order.id)), shipment: shipments.get(String(order.id)) })); setRows(loaded); if (initialOrderId) setSelected(loaded.find((item) => item.id === initialOrderId) ?? null); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os pedidos."); } finally { setLoading(false); } })(); }, [initialOrderId]);
  const customer = (order: any) => order.shipping_address?.full_name || order.customer_name || order.customer_email || "Cliente não identificado";
  const payment = (order: any) => order.payment?.status || order.payment?.payment_status || order.payment_status || order.payment_method || "—";
  const transport = (order: any) => order.shipment?.status || order.shipping_status || "—";
  const values = (field: string) => [...new Set(rows.map((row) => field === "payment" ? payment(row) : field === "shipping" ? transport(row) : row[field]).filter(Boolean))];
  async function openDetails(id: string) { try { setError(""); setSelected(await getAdminOrder(id)); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os detalhes do pedido."); } }
  const filtered = rows.filter((order) => { const text = `${order.order_number || order.id} ${customer(order)}`.toLowerCase(); const date = new Date(order.created_at).getTime(); const days = period === "7" ? 7 : period === "30" ? 30 : period === "90" ? 90 : 0; return text.includes(query.toLowerCase()) && (orderStatus === "all" || String(order.status || "").toLowerCase() === orderStatus.toLowerCase()) && (paymentStatus === "all" || payment(order).toLowerCase() === paymentStatus.toLowerCase()) && (shippingStatus === "all" || transport(order).toLowerCase() === shippingStatus.toLowerCase()) && (!days || date >= Date.now() - days * 86400000); });
  return <div className="mt-8 space-y-6">{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="grid gap-3 rounded-xl border border-border bg-card p-4 md:grid-cols-5"><label className="text-sm font-medium md:col-span-2">Buscar pedido ou cliente<input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Número ou nome/e-mail" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm font-medium">Período<select value={period} onChange={(event) => setPeriod(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todo o período</option><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option></select></label><label className="text-sm font-medium">Pedido<select value={orderStatus} onChange={(event) => setOrderStatus(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option>{values("status").map((item) => <option key={item}>{item}</option>)}</select></label><label className="text-sm font-medium">Pagamento<select value={paymentStatus} onChange={(event) => setPaymentStatus(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option>{values("payment").map((item) => <option key={item}>{item}</option>)}</select></label><label className="text-sm font-medium">Transporte<select value={shippingStatus} onChange={(event) => setShippingStatus(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option>{values("shipping").map((item) => <option key={item}>{item}</option>)}</select></label></div>{selected && <OrderDetails order={selected} onClose={() => setSelected(null)} />}<div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[1050px] text-left text-sm"><thead className="border-b border-border text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Pedido</th><th className="p-4">Cliente</th><th className="p-4">Data e hora</th><th className="p-4">Valor total</th><th className="p-4">Pagamento</th><th className="p-4">Pedido</th><th className="p-4">Transporte</th><th className="p-4">Ação</th></tr></thead><tbody>{loading ? <tr><td colSpan={8} className="p-8 text-center text-muted-foreground">Carregando pedidos reais...</td></tr> : filtered.length === 0 ? <tr><td colSpan={8} className="p-8 text-center text-muted-foreground">Nenhum pedido encontrado.</td></tr> : filtered.map((order) => <tr key={order.id} className="border-b border-border last:border-0"><td className="p-4 font-medium">{order.order_number || order.id}</td><td className="p-4">{customer(order)}</td><td className="p-4 text-muted-foreground">{new Date(order.created_at).toLocaleString("pt-BR")}</td><td className="p-4">R$ {Number(order.total || 0).toFixed(2).replace(".", ",")}</td><td className="p-4">{payment(order)}</td><td className="p-4">{order.status || "—"}</td><td className="p-4">{transport(order)}</td><td className="p-4"><button type="button" onClick={() => void openDetails(order.id)} className="text-primary hover:underline">Abrir detalhes</button></td></tr>)}</tbody></table></div></div>;
}

type Supplier = { id: string; name: string; country: string | null; city: string | null; state: string | null; contact_name: string | null; contact_email: string | null; contact_phone: string | null; status: string; integration_status: string };

function SuppliersManager() {
  return <AdminSuppliers />;
}

function SuppliersManagerLegacy() {
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState("all");
  const [selected, setSelected] = useState<Supplier | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => { void (async () => {
    if (!supabase) { setError("Supabase não está configurado."); setLoading(false); return; }
    const { data, error: requestError } = await supabase.from("suppliers").select("*").order("name");
    if (requestError) setError("Não foi possível carregar os fornecedores. Verifique a tabela suppliers no Supabase.");
    else setSuppliers((data ?? []) as Supplier[]);
    setLoading(false);
  })(); }, []);

  const filtered = suppliers.filter((supplier) => {
    const text = [supplier.name, supplier.country, supplier.city, supplier.state, supplier.contact_name, supplier.contact_email].filter(Boolean).join(" ").toLowerCase();
    return text.includes(query.toLowerCase()) && (status === "all" || supplier.status === status);
  });
  const statuses = [...new Set(suppliers.map((supplier) => supplier.status).filter(Boolean))];
  const contact = (supplier: Supplier) => supplier.contact_name || supplier.contact_email || supplier.contact_phone || "Não informado";
  return <div className="mt-8 space-y-6">
    <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><p className="text-sm text-muted-foreground">Gestão e conexão operacional</p><h2 className="mt-1 text-2xl font-semibold">Fornecedores</h2></div><button type="button" onClick={() => setError("O cadastro será habilitado após a estrutura suppliers ser criada no Supabase.")} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground transition hover:opacity-90">Adicionar fornecedor</button></div>
    <div className="grid gap-3 rounded-xl border border-border bg-card p-4 md:grid-cols-[1fr_12rem]"><label className="text-sm font-medium">Buscar fornecedor<input aria-label="Buscar fornecedor" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Nome, país ou contato" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm font-medium">Status<select aria-label="Filtrar por status" value={status} onChange={(event) => setStatus(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option>{statuses.map((item) => <option key={item} value={item}>{item}</option>)}</select></label></div>
    {error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}
    {selected && <section className="rounded-xl border border-primary/40 bg-card p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-xs uppercase tracking-[0.2em] text-primary">Dados do fornecedor</p><h3 className="mt-2 text-2xl font-semibold">{selected.name}</h3></div><button type="button" onClick={() => setSelected(null)} className="text-sm text-muted-foreground hover:text-foreground">Fechar</button></div><div className="mt-5 grid gap-3 text-sm md:grid-cols-2"><p><span className="text-muted-foreground">País:</span> {selected.country || "—"}</p><p><span className="text-muted-foreground">Local:</span> {[selected.city, selected.state].filter(Boolean).join(" / ") || "—"}</p><p><span className="text-muted-foreground">Contato:</span> {contact(selected)}</p><p><span className="text-muted-foreground">Integração:</span> {selected.integration_status || "Não configurada"}</p></div></section>}
    <div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[720px] text-left text-sm"><thead className="border-b border-border text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Fornecedor</th><th className="p-4">País</th><th className="p-4">Cidade / estado</th><th className="p-4">Contato</th><th className="p-4">Status</th><th className="p-4">Integração</th></tr></thead><tbody>{loading ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Carregando fornecedores...</td></tr> : filtered.length === 0 ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Nenhum fornecedor encontrado.</td></tr> : filtered.map((supplier) => <tr key={supplier.id} tabIndex={0} role="button" onClick={() => setSelected(supplier)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") setSelected(supplier); }} className="cursor-pointer border-b border-border transition hover:bg-muted/50 focus-visible:bg-muted/50 last:border-0"><td className="p-4 font-medium text-primary">{supplier.name}</td><td className="p-4">{supplier.country || "—"}</td><td className="p-4">{[supplier.city, supplier.state].filter(Boolean).join(" / ") || "—"}</td><td className="p-4">{contact(supplier)}</td><td className="p-4">{supplier.status || "—"}</td><td className="p-4">{supplier.integration_status || "Não configurada"}</td></tr>)}</tbody></table></div>
  </div>;
}

function InventoryArea({ area, onAreaChange }: { area: "Estoque" | "Movimentações" | "Reservas" | "Alertas"; onAreaChange: (area: "Estoque" | "Movimentações" | "Reservas" | "Alertas") => void }) {
  return <div className="mt-8 space-y-6"><nav aria-label="Navegação de Estoque" className="flex flex-wrap gap-2 border-b border-border">{(["Estoque", "Movimentações", "Reservas", "Alertas"] as const).map((item) => <button key={item} type="button" onClick={() => onAreaChange(item)} className={`border-b-2 px-3 py-2 text-sm transition ${area === item ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground"}`}>{item}</button>)}</nav><div key={area}>{area === "Estoque" ? <InventoryManager /> : area === "Movimentações" ? <InventoryMovementsManager /> : area === "Reservas" ? <RealReservationsManager /> : <InventoryAlertsManager />}</div></div>;
}

function AdminAlertsPage({ onOpenArea, onOpenOrder }: { onOpenArea: (area: "Estoque" | "Reservas") => void; onOpenOrder: (orderId: string) => void }) {
  const [products, setProducts] = useState<AdminProduct[]>([]);
  const [carts, setCarts] = useState<any[]>([]);
  const [payments, setPayments] = useState<any[]>([]);
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [now, setNow] = useState(Date.now());

  async function load() {
    try {
      setLoading(true); setError("");
      if (!supabase) throw new Error("Supabase não está configurado.");
      const [productRows, cartResult, itemResult, paymentResult, orderResult] = await Promise.all([
        listAdminProducts(),
        supabase.from("carts").select("id,expires_at,status,payment_status,created_at"),
        supabase.from("cart_items").select("cart_id"),
        supabase.from("payments").select("*"),
        supabase.from("orders").select("id,order_number,total,created_at,shipping_address,customer_name,customer_email")
      ]);
      if (cartResult.error) throw cartResult.error;
      if (itemResult.error) throw itemResult.error;
      if (paymentResult.error) throw paymentResult.error;
      if (orderResult.error) throw orderResult.error;
      const cartIds = new Set((itemResult.data ?? []).map((item: any) => String(item.cart_id)));
      setProducts(productRows); setCarts((cartResult.data ?? []).filter((cart: any) => cartIds.has(String(cart.id)))); setPayments(paymentResult.data ?? []); setOrders(orderResult.data ?? []);
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os alertas reais."); }
    finally { setLoading(false); }
  }

  useEffect(() => { void load(); const timer = window.setInterval(() => setNow(Date.now()), 60000); return () => window.clearInterval(timer); }, []);
  const stockAlerts = products.flatMap((product) => product.product_variants.map((variant) => ({ product, variant })).filter(({ variant }) => variant.stock_quantity <= 5));
  const reservationAlerts = carts.filter((cart) => {
    const status = String(cart.status ?? cart.payment_status ?? "active").toLowerCase();
    const expires = cart.expires_at ? new Date(cart.expires_at).getTime() : 0;
    return expires > now && expires - now <= 24 * 60 * 60 * 1000 && !["paid", "pago", "completed", "finalized", "finalizada", "expired", "expirada", "deleted", "removed"].includes(status);
  });
  const dateLabel = (value: string | undefined) => value ? new Date(value).toLocaleString("pt-BR") : "Data não informada";
  const level = (zero: boolean) => zero ? "Crítico" : "Atenção";
  const orderMap = new Map(orders.map((order) => [String(order.id), order]));
  const paymentAlerts = payments.map((payment) => {
    const status = String(payment.status ?? payment.payment_status ?? "").toLowerCase();
    const order = orderMap.get(String(payment.order_id ?? payment.external_reference ?? ""));
    const approved = ["approved", "confirmed", "paid", "pago", "aprovado", "confirmado"].includes(status);
    const failed = ["rejected", "failed", "failure", "recusado", "rejeitado", "falhou"].includes(status);
    return { payment, order, status, level: approved ? "success" : failed ? "danger" : "warning", label: approved ? "Pagamento aprovado" : failed ? "Pagamento rejeitado/falhou" : "Pagamento pendente" };
  });
  const operationalAlerts = [
    ...paymentAlerts.filter(({ level }) => level === "danger").map(({ payment, order, status }) => ({ key: `payment-${payment.id}`, title: "Falha de processamento de pagamento", message: `O pedido ${order?.order_number || order?.id || payment.order_id || "não identificado"} possui pagamento ${status || "falho"}.`, date: payment.updated_at || payment.created_at || order?.created_at, level: "Crítico", action: order?.id ? "Abrir pedido" : "Abrir pagamentos", onOpen: order?.id ? () => onOpenOrder(order.id) : undefined })),
    ...products.flatMap((product) => product.product_variants.filter((variant) => variant.stock_quantity === 0).map((variant) => ({ key: `stock-${variant.id}`, title: "Produto sem estoque", message: `${product.name} não possui unidades disponíveis para venda${variant.sku ? ` (SKU ${variant.sku})` : ""}.`, date: undefined, level: "Crítico", action: "Abrir estoque", onOpen: () => onOpenArea("Estoque") }))),
  ];
  const card = (title: string, children: React.ReactNode, description: string, count: number) => <section className="rounded-xl border border-border bg-card p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="text-xl font-semibold">{title}</h2><p className="mt-1 text-sm text-muted-foreground">{description}</p></div><span className="rounded-full border border-border px-2 py-1 text-xs text-muted-foreground">{count}</span></div>{children}</section>;
  const empty = (text: string) => <div className="mt-5 rounded-lg border border-dashed border-border bg-muted/30 p-5 text-sm text-muted-foreground">{text}</div>;
  return <div className="mt-8 space-y-6"><p className="max-w-2xl text-sm leading-relaxed text-muted-foreground">Alertas calculados a partir dos dados reais de variantes e reservas. A consulta não altera estoque, reservas ou pedidos.</p>{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}{loading ? <div className="rounded-xl border border-border bg-card p-8 text-sm text-muted-foreground">Carregando alertas reais...</div> : <div className="grid gap-5 lg:grid-cols-2">{card("Estoque", stockAlerts.length === 0 ? empty("Nenhum alerta de estoque no momento.") : <div className="mt-5 space-y-3">{stockAlerts.map(({ product, variant }) => { const zero = variant.stock_quantity === 0; return <article key={variant.id} className="rounded-lg border border-border p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-medium">{zero ? "Estoque zerado" : "Estoque baixo"}</p><p className="text-sm text-muted-foreground">{product.name} · {variant.color || "Sem cor"} / {variant.size || "Sem tamanho"} · {variant.stock_quantity} unidade(s)</p></div><span className={zero ? "text-destructive" : "text-primary"}>{level(zero)}</span></div><p className="mt-2 text-xs text-muted-foreground">Verificado em {dateLabel(new Date().toISOString())}</p><button type="button" onClick={() => onOpenArea("Estoque")} className="mt-3 text-sm text-primary hover:underline">Abrir estoque</button></article>; })}</div>, "Variantes zeradas ou abaixo de 5 unidades", stockAlerts.length)}{card("Reservas", reservationAlerts.length === 0 ? empty("Nenhuma reserva próxima da expiração.") : <div className="mt-5 space-y-3">{reservationAlerts.map((cart) => { const minutes = Math.max(0, Math.floor((new Date(cart.expires_at).getTime() - now) / 60000)); return <article key={cart.id} className="rounded-lg border border-border p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-medium">Reserva próxima da expiração</p><p className="text-sm text-muted-foreground">Expira em {Math.floor(minutes / 60)}h {minutes % 60}min · criada em {dateLabel(cart.created_at)}</p></div><span className="text-primary">Atenção</span></div><p className="mt-2 text-xs text-muted-foreground">Expiração: {dateLabel(cart.expires_at)}</p><button type="button" onClick={() => onOpenArea("Reservas")} className="mt-3 text-sm text-primary hover:underline">Abrir reservas</button></article>; })}</div>, "Reservas reais com vencimento nas próximas 24 horas", reservationAlerts.length)}{card("Pagamentos", paymentAlerts.length === 0 ? empty("Nenhum pagamento persistido encontrado.") : <div className="mt-5 space-y-3">{paymentAlerts.map(({ payment, order, status, level: paymentLevel, label }) => <article key={String(payment.id)} className="rounded-lg border border-border p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-medium">{label}</p><p className="text-sm text-muted-foreground">Pedido: {order?.order_number || order?.id || payment.order_id || "Não vinculado"} · Cliente: {order?.shipping_address?.full_name || order?.customer_name || order?.customer_email || "Não disponível"}</p></div><span className={paymentLevel === "success" ? "text-emerald-600" : paymentLevel === "danger" ? "text-destructive" : "text-primary"}>{status || "Status não informado"}</span></div><p className="mt-2 text-xs text-muted-foreground">Valor: R$ {Number(payment.amount ?? payment.transaction_amount ?? order?.total ?? 0).toFixed(2).replace(".", ",")} · {dateLabel(payment.created_at || payment.updated_at || order?.created_at)}</p>{order?.id && <button type="button" onClick={() => onOpenOrder(order.id)} className="mt-3 text-sm text-primary hover:underline">Abrir pedido</button>}</article>)}</div>, "Status persistidos em payments e relacionados aos pedidos", paymentAlerts.length)}{card("Problemas do sistema", operationalAlerts.length === 0 ? empty("Nenhum problema operacional registrado no momento.") : <div className="mt-5 space-y-3">{operationalAlerts.map((alert) => <article key={alert.key} className="rounded-lg border border-border p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-medium">{alert.title}</p><p className="text-sm text-muted-foreground">{alert.message}</p></div><span className={alert.level === "Crítico" ? "text-destructive" : "text-primary"}>{alert.level}</span></div><p className="mt-2 text-xs text-muted-foreground">{alert.date ? `Registrado em ${dateLabel(alert.date)}` : "Situação atual do catálogo"}</p>{alert.onOpen && <button type="button" onClick={alert.onOpen} className="mt-3 text-sm text-primary hover:underline">{alert.action}</button>}</article>)}</div>, "Falhas e situações operacionais identificadas nos dados persistidos", operationalAlerts.length)}</div>}</div>;
}

function InventoryAlertsManager() {
  const [products, setProducts] = useState<AdminProduct[]>([]); const [stock, setStock] = useState<InventoryRow[]>([]); const [limits, setLimits] = useState<Record<string, string>>({}); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState<string | null>(null); const [error, setError] = useState("");
  async function load() { try { setLoading(true); const [productRows, stockRows] = await Promise.all([listAdminProducts(), listInventory()]); setProducts(productRows); setStock(stockRows); setLimits(Object.fromEntries(stockRows.map((row) => [row.variant_id, String(row.minimum_quantity ?? 5)]))); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os alertas."); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []);
  const details = new Map(stock.map((row) => [row.variant_id, row]));
  const alerts = products.flatMap((product) => product.product_variants.map((variant) => ({ product, variant, row: details.get(variant.id) })).filter(({ variant, row }) => variant.stock_quantity === 0 || variant.stock_quantity <= Number(limits[variant.id] ?? row?.minimum_quantity ?? 5)));
  async function saveLimit(variantId: string) { const value = Number(limits[variantId]); if (!Number.isInteger(value) || value < 0) return; try { setSaving(variantId); await updateInventoryMinimum(variantId, value); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível salvar o limite."); } finally { setSaving(null); } }
  return <div className="space-y-6">{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full text-left text-sm"><thead className="border-b border-border text-muted-foreground"><tr><th className="p-4">Produto</th><th className="p-4">Variante</th><th className="p-4">Estoque atual</th><th className="p-4">Status</th><th className="p-4">Limite de estoque baixo</th><th className="p-4">Ação</th></tr></thead><tbody>{loading ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Carregando alertas...</td></tr> : alerts.length === 0 ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Nenhum produto com estoque baixo ou zerado.</td></tr> : alerts.map(({ product, variant }) => <tr key={variant.id} className="border-b border-border last:border-0"><td className="p-4 font-medium">{product.name}</td><td className="p-4">{variant.sku} · {variant.size || "Sem tamanho"} · {variant.color || "Sem cor"}</td><td className="p-4">{variant.stock_quantity}</td><td className="p-4 text-destructive">{variant.stock_quantity === 0 ? "Zerado" : "Estoque baixo"}</td><td className="p-4"><input type="number" min="0" step="1" value={limits[variant.id] ?? "5"} onChange={(event) => setLimits({ ...limits, [variant.id]: event.target.value })} className="w-28 rounded-lg border border-input bg-background px-3 py-2" /></td><td className="p-4"><button type="button" disabled={saving === variant.id} onClick={() => void saveLimit(variant.id)} className="text-primary hover:underline">{saving === variant.id ? "Salvando..." : "Salvar limite"}</button></td></tr>)}</tbody></table></div></div>;
}

function InventoryMovementsManager() {
  const [rows, setRows] = useState<any[]>([]); const [selected, setSelected] = useState<any | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  const [from, setFrom] = useState(""); const [to, setTo] = useState("");
  async function load() {
    try {
      setLoading(true); setError("");
      if (!supabase) throw new Error("Supabase não configurado.");
      const [movementResult, orderResult, shipmentResult, returnResult, productRows] = await Promise.all([
        listInventoryMovements(),
        supabase.from("orders").select("id,order_number,total,status,created_at,order_items(*)").order("created_at", { ascending: false }),
        supabase.from("shipments").select("id,order_id,status,created_at").order("created_at", { ascending: false }),
        supabase.from("returns").select("id,order_id,status,created_at,return_items(*)").order("created_at", { ascending: false }),
        listAdminProducts(),
      ]);
      if (orderResult.error) throw orderResult.error; if (shipmentResult.error) throw shipmentResult.error; if (returnResult.error) throw returnResult.error;
      const variants = new Map(productRows.flatMap((product) => product.product_variants.map((variant) => [variant.id, { product: product.name, variant: `${variant.sku} · ${variant.size || "Sem tamanho"} · ${variant.color || "Sem cor"}` }])));
      const orders = orderResult.data ?? []; const shipments = shipmentResult.data ?? []; const returns = returnResult.data ?? [];
      const orderById = new Map(orders.map((order) => [order.id, order]));
      const result = [
        ...movementResult.map((item) => { const detail = variants.get(item.variant_id); return { id: `movement-${item.id}`, date: item.created_at, type: item.movement_type === "entry" ? "Entrada de estoque" : item.movement_type === "exit" ? "Saída de estoque" : "Ajuste de estoque", product: detail?.product || "Produto não encontrado", variant: detail?.variant || item.variant_id, quantity: item.quantity, value: null, status: item.note || "Registrada" }; }),
        ...orders.map((order) => ({ id: `sale-${order.id}`, date: order.created_at, type: "Venda", product: "Pedido", variant: order.order_number || order.id, quantity: (order.order_items || []).reduce((sum: number, item: any) => sum + Number(item.quantity || 0), 0), value: Number(order.total || 0), status: order.status || "—" })),
        ...shipments.map((shipment) => ({ id: `shipment-${shipment.id}`, date: shipment.created_at, type: ["delivered", "entregue"].includes(String(shipment.status).toLowerCase()) ? "Produtos entregues" : "Produtos enviados", product: "Pedido", variant: orderById.get(shipment.order_id)?.order_number || shipment.order_id, quantity: null, value: null, status: shipment.status || "—" })),
        ...returns.map((item) => ({ id: `return-${item.id}`, date: item.created_at, type: "Devolução / produtos retornados", product: "Pedido", variant: orderById.get(item.order_id)?.order_number || item.order_id, quantity: (item.return_items || []).reduce((sum: number, entry: any) => sum + Number(entry.quantity || 0), 0) || null, value: null, status: item.status || "—" })),
      ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setRows(result);
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar o histórico."); } finally { setLoading(false); }
  }
  useEffect(() => { void load(); }, []);
  const filtered = rows.filter((row) => { const date = new Date(row.date); const start = from ? new Date(`${from}T00:00:00`) : null; const end = to ? new Date(`${to}T23:59:59`) : null; return (!start || date >= start) && (!end || date <= end); });
  const sales = filtered.filter((row) => row.type === "Venda"); const totalSales = sales.reduce((sum, row) => sum + Number(row.value || 0), 0);
  const metric = (label: string, value: string) => <article className="rounded-xl border border-border bg-card p-5"><p className="text-xs uppercase tracking-wider text-muted-foreground">{label}</p><p className="mt-3 text-2xl font-semibold tabular-nums">{loading ? "—" : value}</p></article>;
  function exportRow(row: any) { const blob = new Blob([JSON.stringify(row, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `movimentacao-${row.id}.json`; link.click(); URL.revokeObjectURL(url); }
  return <div className="space-y-6">{selected && <section className="rounded-xl border border-primary/40 bg-card p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-xs uppercase tracking-[0.2em] text-primary">Detalhes da movimentação</p><h2 className="mt-2 text-xl font-semibold">{selected.type}</h2></div><div className="flex gap-3"><button type="button" onClick={() => exportRow(selected)} className="rounded-lg border border-border px-3 py-2 text-sm text-primary">Baixar arquivo</button><button type="button" onClick={() => setSelected(null)} className="text-sm text-muted-foreground">Fechar</button></div></div><div className="mt-4 grid gap-3 text-sm md:grid-cols-2"><p>Data: {new Date(selected.date).toLocaleString("pt-BR")}</p><p>Status: {selected.status}</p><p>Produto: {selected.product}</p><p>Variante/pedido: {selected.variant}</p><p>Quantidade: {selected.quantity ?? "—"}</p><p>Valor: {selected.value == null ? "—" : `R$ ${selected.value.toFixed(2)}`}</p></div><pre className="mt-4 max-h-64 overflow-auto rounded-lg bg-muted p-4 text-xs">{JSON.stringify(selected, null, 2)}</pre></section>}{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{metric("Total de vendas", `R$ ${totalSales.toFixed(2)}`)}{metric("Vendas no período", String(sales.length))}{metric("Entradas de estoque", String(filtered.filter((row) => row.type === "Entrada de estoque").length))}{metric("Saídas de estoque", String(filtered.filter((row) => row.type === "Saída de estoque").length))}</div><div className="grid gap-4 rounded-xl border border-border bg-card p-4 md:grid-cols-[1fr_1fr_auto]"><label className="text-sm font-medium">Data inicial<input type="date" value={from} onChange={(event) => setFrom(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm font-medium">Data final<input type="date" value={to} onChange={(event) => setTo(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><button type="button" onClick={() => { setFrom(""); setTo(""); }} className="self-end rounded-lg border border-border px-4 py-2 text-sm hover:border-primary hover:text-primary">Limpar período</button></div><div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[900px] text-left text-sm"><thead className="border-b border-border text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Data e hora</th><th className="p-4">Tipo</th><th className="p-4">Produto</th><th className="p-4">Variante</th><th className="p-4">Quantidade</th><th className="p-4">Valor</th><th className="p-4">Status</th></tr></thead><tbody>{loading ? <tr><td colSpan={7} className="p-8 text-center text-muted-foreground">Carregando histórico...</td></tr> : filtered.length === 0 ? <tr><td colSpan={7} className="p-8 text-center text-muted-foreground">Nenhuma operação encontrada no período.</td></tr> : filtered.map((row) => <tr key={row.id} tabIndex={0} role="button" onClick={() => setSelected(row)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") setSelected(row); }} className="cursor-pointer border-b border-border transition hover:bg-muted/50 focus-visible:bg-muted/50 last:border-0"><td className="p-4 text-muted-foreground">{new Date(row.date).toLocaleString("pt-BR")}</td><td className="p-4 font-medium">{row.type}</td><td className="p-4">{row.product}</td><td className="p-4">{row.variant}</td><td className="p-4">{row.quantity ?? "—"}</td><td className="p-4">{row.value == null ? "—" : `R$ ${row.value.toFixed(2)}`}</td><td className="p-4">{row.status}</td></tr>)}</tbody></table></div></div>;
}

function RealReservationsManager() {
  const [rows, setRows] = useState<any[]>([]); const [selected, setSelected] = useState<any | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [now, setNow] = useState(Date.now()); const [eliminating, setEliminating] = useState(false);
  async function load() {
    if (!supabase) { setError("Supabase não configurado."); setLoading(false); return; }
    try {
      setLoading(true); setError("");
      const [cartsResult, itemsResult, products] = await Promise.all([
        supabase.from("carts").select("*").order("created_at", { ascending: false }),
        supabase.from("cart_items").select("*"),
        listAdminProducts(),
      ]);
      if (cartsResult.error) throw cartsResult.error;
      if (itemsResult.error) throw itemsResult.error;
      const productMap = new Map(products.map((product) => [product.id, product]));
      const variantMap = new Map(products.flatMap((product) => product.product_variants.map((variant) => [variant.id, { product, variant }])));
      const itemsByCart = new Map<string, any[]>();
      (itemsResult.data ?? []).forEach((item: any) => { const list = itemsByCart.get(String(item.cart_id)) ?? []; list.push(item); itemsByCart.set(String(item.cart_id), list); });
      setRows((cartsResult.data ?? []).map((cart: any) => {
        const items = (itemsByCart.get(String(cart.id)) ?? []).map((item: any) => { const detail = item.variant_id ? variantMap.get(item.variant_id) : productMap.get(item.product_id) ? { product: productMap.get(item.product_id), variant: null } : undefined; return { ...item, product: detail?.product, variant: detail?.variant }; });
        const total = items.reduce((sum, item) => sum + Number(item.quantity || 0) * Number(item.unit_price ?? item.price ?? 0), 0);
        return { ...cart, items, total };
      }).filter((cart: any) => cart.items.length > 0));
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar as reservas reais."); }
    finally { setLoading(false); }
  }
  useEffect(() => { void load(); const timer = window.setInterval(() => setNow(Date.now()), 60000); return () => window.clearInterval(timer); }, []);
  async function eliminateReservation(cart: any) {
    if (!supabase || statusOf(cart) !== "active") return;
    if (!window.confirm("Eliminar esta reserva e liberar o estoque correspondente?")) return;
    try {
      setEliminating(true); setError("");
      const { error: releaseError } = await supabase.rpc("release_cart_reservation", { p_cart_id: cart.id });
      if (releaseError) throw releaseError;
      setSelected(null);
      await load();
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível eliminar a reserva usando a rotina de liberação do Supabase."); }
    finally { setEliminating(false); }
  }
  const statusOf = (cart: any) => { const value = String(cart.status ?? cart.payment_status ?? "active").toLowerCase(); if (["expired", "expirada", "eliminada", "deleted", "removed"].includes(value) || (cart.expires_at && new Date(cart.expires_at).getTime() <= now)) return "expired"; if (["paid", "pago", "completed", "finalized", "finalizada"].includes(value)) return "finished"; return "active"; };
  const groups = [{ key: "active", label: "Ativas" }, { key: "finished", label: "Pagamento recebido / finalizadas" }, { key: "expired", label: "Expiradas / eliminadas manualmente" }];
  const money = (value: number) => `R$ ${value.toFixed(2).replace(".", ",")}`;
  const customer = (cart: any) => cart.customer_name || cart.customer_email || cart.email || cart.user_email || cart.user_id || "Cliente não identificado";
  const contact = (cart: any) => cart.customer_phone || cart.phone || cart.whatsapp || cart.customer_email || "Contato não informado";
  const timeLeft = (cart: any) => { if (!cart.expires_at) return "Sem prazo registrado"; const difference = new Date(cart.expires_at).getTime() - now; if (difference <= 0) return "Expirada"; const minutes = Math.floor(difference / 60000); return `${Math.floor(minutes / 60)}h ${minutes % 60}min restantes`; };
  const group = (key: string, label: string) => { const list = rows.filter((row) => statusOf(row) === key); return <section key={key} className="space-y-3"><div><h2 className="text-xl font-semibold">{label}</h2><p className="text-sm text-muted-foreground">{list.length} reserva(s) real(is)</p></div>{list.length === 0 ? <div className="rounded-xl border border-dashed border-border bg-card p-6 text-sm text-muted-foreground">Nenhuma reserva real nesta categoria.</div> : <div className="space-y-4">{list.map((cart) => <article key={cart.id} role="button" tabIndex={0} onClick={() => setSelected(cart)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") setSelected(cart); }} className="cursor-pointer rounded-xl border border-border bg-card p-5 transition hover:bg-muted/50 focus-visible:bg-muted/50"><div className="flex flex-wrap items-start justify-between gap-4"><div><h3 className="font-semibold">{customer(cart)}</h3><p className="text-sm text-muted-foreground">{contact(cart)} · {cart.created_at ? new Date(cart.created_at).toLocaleString("pt-BR") : "Data não informada"}</p></div><div className="text-right text-sm"><p className="font-medium">{money(cart.total)}</p><p className="text-primary">{cart.payment_status || cart.status || "Pagamento pendente"}</p><p className="text-muted-foreground">{timeLeft(cart)}</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{cart.items.map((item: any, index: number) => { const product = item.product; const variant = item.variant; const image = product?.product_images?.find((entry: any) => entry.is_primary) ?? product?.product_images?.[0]; return <div key={item.id || index} className="flex gap-3 rounded-lg border border-border p-3"><div className="h-16 w-12 shrink-0 overflow-hidden rounded-md bg-muted">{image ? <img src={image.image_url} alt={image.alt_text || product.name} className="h-full w-full object-cover" /> : null}</div><div className="min-w-0 text-sm"><p className="truncate font-medium">{product?.name || item.product_name || "Produto não identificado"}</p><p className="text-muted-foreground">Cor: {variant?.color || item.color || "—"} · Tamanho: {variant?.size || item.size || "—"}</p><p className="text-muted-foreground">Qtd.: {item.quantity || 0} · {money(Number(item.unit_price ?? item.price ?? 0))}</p></div></div>; })}</div></article>)}</div>}</section>; };
  return <div className="space-y-8">{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}{selected && <section className="rounded-xl border border-primary/40 bg-card p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-xs uppercase tracking-[0.2em] text-primary">Detalhes da reserva</p><h2 className="mt-2 text-2xl font-semibold">{customer(selected)}</h2><p className="text-sm text-muted-foreground">{contact(selected)} · {selected.created_at ? new Date(selected.created_at).toLocaleString("pt-BR") : "Data não informada"}</p></div><button type="button" onClick={() => setSelected(null)} className="text-sm text-muted-foreground hover:text-foreground">Fechar</button></div><div className="mt-5 grid gap-3 text-sm md:grid-cols-3"><p>Status do pagamento: <strong>{selected.payment_status || selected.status || "Pagamento pendente"}</strong></p><p>Total: <strong>{money(selected.total)}</strong></p><p>Expiração: <strong>{timeLeft(selected)}</strong></p></div><div className="mt-5 space-y-2 border-t border-border pt-4">{selected.items.map((item: any, index: number) => <p key={item.id || index} className="text-sm">{item.product?.name || item.product_name || "Produto não identificado"} · {item.variant?.color || item.color || "—"} / {item.variant?.size || item.size || "—"} · {item.quantity || 0} un. · {money(Number(item.unit_price ?? item.price ?? 0))}</p>)}</div>{statusOf(selected) === "active" && <button type="button" disabled={eliminating} onClick={() => void eliminateReservation(selected)} className="mt-5 rounded-lg bg-destructive px-4 py-2 text-sm text-destructive-foreground disabled:opacity-50">{eliminating ? "Liberando estoque..." : "Eliminar reserva e liberar estoque"}</button>}</section>}{loading ? <div className="rounded-xl border border-border bg-card p-8 text-sm text-muted-foreground">Carregando reservas reais...</div> : groups.map((entry) => group(entry.key, entry.label))}</div>;
}

function InventoryReservationsManager() {
  const [reservations, setReservations] = useState<InventoryReservation[]>([]);
  const [products, setProducts] = useState<AdminProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useEffect(() => { void (async () => { try { setLoading(true); const [reservationRows, productRows] = await Promise.all([listInventoryReservations(), listAdminProducts()]); setReservations(reservationRows); setProducts(productRows); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar as reservas."); } finally { setLoading(false); } })(); }, []);
  const variants = new Map(products.flatMap((product) => product.product_variants.map((variant) => [variant.id, { product: product.name, variant: `${variant.sku} · ${variant.size || "Sem tamanho"} · ${variant.color || "Sem cor"}` }])));
  return <div className="space-y-6">{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full text-left text-sm"><thead className="border-b border-border text-muted-foreground"><tr><th className="p-4">Produto</th><th className="p-4">Variante</th><th className="p-4">Quantidade</th><th className="p-4">Status</th><th className="p-4">Data</th></tr></thead><tbody>{loading ? <tr><td colSpan={5} className="p-8 text-center text-muted-foreground">Carregando reservas...</td></tr> : reservations.length === 0 ? <tr><td colSpan={5} className="p-8 text-center text-muted-foreground">Nenhuma reserva registrada.</td></tr> : reservations.map((reservation) => { const variant = variants.get(reservation.variant_id); return <tr key={reservation.id} className="border-b border-border last:border-0"><td className="p-4 font-medium">{variant?.product || "Produto não encontrado"}</td><td className="p-4">{variant?.variant || reservation.variant_id}</td><td className="p-4">{reservation.quantity}</td><td className="p-4">{reservation.status}</td><td className="p-4 text-muted-foreground">{new Date(reservation.created_at).toLocaleString("pt-BR")}</td></tr>; })}</tbody></table></div></div>;
}

function InventoryManager() {
  const [products, setProducts] = useState<AdminProduct[]>([]);
  const [selected, setSelected] = useState<{ product: AdminProduct; variant: AdminProduct["product_variants"][number] } | null>(null);
  const [addition, setAddition] = useState("0");
  const [removal, setRemoval] = useState("0");
  const [reason, setReason] = useState("");
  const [savingAdjustment, setSavingAdjustment] = useState(false);
  const [query, setQuery] = useState("");
  const [stockFilter, setStockFilter] = useState<"all" | "low" | "zero">("all");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const lowLimit = 5;

  async function load() {
    try { setLoading(true); setError(""); setProducts(await listAdminProducts()); }
    catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar o estoque."); }
    finally { setLoading(false); }
  }
  useEffect(() => { void load(); }, []);

  const rows = products.flatMap((product) => product.product_variants.map((variant) => ({ product, variant })));
  const filtered = rows.filter(({ product, variant }) => {
    const searchable = `${product.name} ${variant.sku}`.toLowerCase();
    const matchesQuery = searchable.includes(query.toLowerCase());
    const matchesStock = stockFilter === "all" || (stockFilter === "zero" ? variant.stock_quantity === 0 : variant.stock_quantity > 0 && variant.stock_quantity <= lowLimit);
    return matchesQuery && matchesStock;
  });
  const imageFor = (product: AdminProduct) => product.product_images.find((image) => image.is_primary) ?? product.product_images[0];
  const totalProducts = products.length;
  const totalUnits = rows.reduce((total, row) => total + Math.max(0, row.variant.stock_quantity), 0);
  const lowStock = rows.filter(({ variant }) => variant.stock_quantity > 0 && variant.stock_quantity <= lowLimit).length;
  const zeroStock = rows.filter(({ variant }) => variant.stock_quantity === 0).length;
  const addAmount = Math.max(0, Number(addition) || 0);
  const removeAmount = Math.max(0, Number(removal) || 0);
  const newBalance = selected ? Math.max(0, selected.variant.stock_quantity + addAmount - removeAmount) : 0;
  async function saveAdjustment(event: React.FormEvent) {
    event.preventDefault();
    if (!selected || !reason.trim() || (addAmount === 0 && removeAmount === 0) || removeAmount > selected.variant.stock_quantity + addAmount) return;
    try {
      setSavingAdjustment(true);
      await adjustVariantStock({ variantId: selected.variant.id, newQuantity: newBalance, movementQuantity: addAmount || removeAmount, movementType: addAmount && removeAmount ? "adjustment" : addAmount ? "entry" : "exit", note: reason.trim() });
      setSelected(null); setAddition("0"); setRemoval("0"); setReason(""); await load();
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível ajustar o estoque."); }
    finally { setSavingAdjustment(false); }
  }
  const metric = (label: string, value: number) => <article className="rounded-xl border border-border bg-card p-5"><p className="text-xs uppercase tracking-wider text-muted-foreground">{label}</p><p className="mt-3 text-2xl font-semibold tabular-nums">{loading ? "—" : value}</p></article>;

  return <div className="space-y-6">
    {error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}
    {selected && <form onSubmit={saveAdjustment} className="space-y-4 rounded-xl border border-primary/40 bg-card p-5"><div className="flex items-start justify-between"><div><p className="text-xs uppercase tracking-[0.2em] text-primary">Ajustar variante</p><div className="mt-2 flex items-center gap-3"><div className="h-16 w-14 overflow-hidden rounded-lg border border-border bg-muted">{imageFor(selected.product) ? <img src={imageFor(selected.product)!.image_url} alt={imageFor(selected.product)!.alt_text || selected.product.name} className="h-full w-full object-cover" /> : null}</div><h2 className="text-xl font-semibold">{selected.product.name}</h2></div></div><button type="button" onClick={() => setSelected(null)} className="text-sm text-muted-foreground">Fechar</button></div><div className="grid gap-3 text-sm md:grid-cols-3"><p>Cor: {selected.variant.color || "—"}</p><p>Tamanho: {selected.variant.size || "—"}</p><p>SKU: {selected.variant.sku}</p><p>Estoque atual: {selected.variant.stock_quantity}</p><p>Novo saldo: <strong>{newBalance}</strong></p></div><div className="grid gap-4 md:grid-cols-2"><label className="text-sm">Adicionar quantidade<input type="number" min="0" step="1" value={addition} onChange={(event) => setAddition(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Retirar quantidade<input type="number" min="0" max={selected.variant.stock_quantity + addAmount} step="1" value={removal} onChange={(event) => setRemoval(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label></div><label className="block text-sm">Motivo da movimentação<textarea required value={reason} onChange={(event) => setReason(event.target.value)} rows={2} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /></label><button disabled={savingAdjustment || !reason.trim() || (addAmount === 0 && removeAmount === 0) || removeAmount > selected.variant.stock_quantity + addAmount} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{savingAdjustment ? "Salvando..." : "Salvar ajuste"}</button></form>}
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{metric("Total de produtos", totalProducts)}{metric("Unidades disponíveis", totalUnits)}{metric("Variantes com estoque baixo", lowStock)}{metric("Variantes sem estoque", zeroStock)}</div>
    <div className="grid gap-3 rounded-xl border border-border bg-card p-4 md:grid-cols-[1fr_12rem]"><label className="text-sm font-medium">Pesquisar produto ou SKU<input aria-label="Pesquisar produto ou SKU no estoque" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Nome do produto ou SKU" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm font-medium">Filtrar estoque<select aria-label="Filtrar estoque" value={stockFilter} onChange={(event) => setStockFilter(event.target.value as typeof stockFilter)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option><option value="low">Baixo</option><option value="zero">Zero</option></select></label></div>
    <div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[800px] text-left text-sm"><thead className="border-b border-border text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Produto</th><th className="p-4">Cor</th><th className="p-4">Tamanho</th><th className="p-4">SKU</th><th className="p-4">Estoque atual</th><th className="p-4">Situação</th></tr></thead><tbody>{loading ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Carregando estoque...</td></tr> : filtered.length === 0 ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Nenhum item de estoque encontrado.</td></tr> : filtered.map(({ product, variant }) => { const image = imageFor(product); const zero = variant.stock_quantity === 0; const low = !zero && variant.stock_quantity <= lowLimit; return <tr key={variant.id} tabIndex={0} role="button" onClick={() => setSelected({ product, variant })} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") setSelected({ product, variant }); }} className="cursor-pointer border-b border-border transition hover:bg-muted/50 focus-visible:bg-muted/50 last:border-0"><td className="p-4"><div className="flex items-center gap-3"><div className="h-14 w-12 overflow-hidden rounded-lg border border-border bg-muted">{image ? <img src={image.image_url} alt={image.alt_text || product.name} className="h-full w-full object-cover" /> : null}</div><span className="font-medium">{product.name}</span></div></td><td className="p-4">{variant.color || "—"}</td><td className="p-4">{variant.size || "—"}</td><td className="p-4 font-mono text-xs">{variant.sku}</td><td className="p-4 font-medium">{variant.stock_quantity}</td><td className={`p-4 font-medium ${zero ? "text-destructive" : low ? "text-primary" : "text-muted-foreground"}`}>{zero ? "Estoque zerado" : low ? "Estoque baixo" : "Disponível"}</td></tr>; })}</tbody></table></div>
    <p className="text-sm text-muted-foreground">{filtered.length} variante(s) encontrada(s). O estoque exibido é o controlado pela LEH para venda.</p>
  </div>;
}

function ProductPromotionsManager() {
  const [products, setProducts] = useState<AdminProduct[]>([]); const [selectedId, setSelectedId] = useState(""); const [promoPrice, setPromoPrice] = useState(""); const [selectedSizes, setSelectedSizes] = useState<string[]>([]); const [promoActive, setPromoActive] = useState(true); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState("");
  async function load() { try { setLoading(true); setError(""); setProducts(await listAdminProducts()); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar as promoções."); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []);
  const selected = products.find((product) => product.id === selectedId);
  const sizeOptions = ["PP", "P", "M", "G", "GG", "XG"];
  function selectProduct(id: string) { const product = products.find((item) => item.id === id); setSelectedId(id); setPromoPrice(product?.compare_at_price != null ? String(product.compare_at_price) : ""); setSelectedSizes([...new Set((product?.product_variants ?? []).filter((variant) => variant.price_override != null).map((variant) => variant.size).filter(Boolean) as string[])]); setPromoActive(Boolean(product?.compare_at_price)); }
  async function savePromotion(event: React.FormEvent) { event.preventDefault(); if (!selected || !promoPrice || Number(promoPrice) <= 0) { setError("Informe um preço promocional válido."); return; } if (Number(promoPrice) >= selected.price) { setError("O preço promocional deve ser menor que o preço original."); return; } try { setSaving(true); setError(""); await updateAdminProductPromotion({ id: selected.id, originalPrice: selected.compare_at_price ?? selected.price, promoPrice: Number(promoPrice), selectedSizes, active: promoActive }); await load(); selectProduct(selected.id); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível salvar a promoção."); } finally { setSaving(false); } }
  const promotions = products.filter((product) => product.compare_at_price != null && product.compare_at_price > product.price);
  const withoutPromotion = products.filter((product) => !promotions.includes(product));
  const imageFor = (product: AdminProduct) => product.product_images.find((image) => image.is_primary) ?? product.product_images[0];
  const stockFor = (product: AdminProduct) => product.product_variants.reduce((total, variant) => total + variant.stock_quantity, 0);
  const discountFor = (product: AdminProduct) => product.compare_at_price ? Math.round((1 - product.price / product.compare_at_price) * 100) : 0;
  const formatPrice = (value: number | null | undefined) => value == null ? "—" : `R$ ${value.toFixed(2)}`;
  function productTable(title: string, rows: AdminProduct[], promoted: boolean) { return <section className="space-y-3"><div><h2 className="text-xl font-semibold">{title}</h2><p className="text-sm text-muted-foreground">{rows.length} produto(s)</p></div><div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[820px] text-left text-sm"><thead className="border-b border-border text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Produto</th><th className="p-4">Preço normal</th><th className="p-4">Preço promocional</th><th className="p-4">Desconto</th><th className="p-4">Estoque atual</th><th className="p-4">Status da promoção</th></tr></thead><tbody>{rows.length === 0 ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Nenhum produto nesta seção.</td></tr> : rows.map((product) => { const image = imageFor(product); return <tr key={product.id} className="border-b border-border last:border-0"><td className="p-4"><div className="flex items-center gap-3"><div className="h-14 w-12 overflow-hidden rounded-lg border border-border bg-muted">{image ? <img src={image.image_url} alt={image.alt_text || product.name} className="h-full w-full object-cover" /> : null}</div><span className="font-medium">{product.name}</span></div></td><td className="p-4">{formatPrice(promoted ? product.compare_at_price : product.price)}</td><td className="p-4 text-primary">{promoted ? formatPrice(product.price) : "—"}</td><td className="p-4">{promoted ? `${discountFor(product)}%` : "—"}</td><td className="p-4">{stockFor(product)}</td><td className="p-4">{promoted ? (product.active ? "Ativa" : "Inativa") : "Sem promoção"}</td></tr>; })}</tbody></table></div></section>; }
  return <div className="space-y-8">{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<form onSubmit={savePromotion} className="space-y-5 rounded-xl border border-primary/40 bg-card p-5"><h2 className="text-xl font-semibold">Cadastrar promoção</h2><label className="block text-sm">Produto<select required value={selectedId} onChange={(event) => selectProduct(event.target.value)} className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2"><option value="">Selecione um produto</option>{products.map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select></label>{selected && <><div className="grid gap-4 text-sm md:grid-cols-3"><p><span className="text-muted-foreground">Produto:</span> {selected.name}</p><p><span className="text-muted-foreground">Preço original:</span> R$ {selected.price.toFixed(2)}</p><p><span className="text-muted-foreground">Estoque atual:</span> {stockFor(selected)}</p></div><div className="grid gap-4 md:grid-cols-2"><label className="text-sm">Preço promocional<input required type="number" min="0.01" step="0.01" value={promoPrice} onChange={(event) => setPromoPrice(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" />{promoPrice && <span className="mt-1 block text-xs text-primary">Desconto: {Math.max(0, Math.round((1 - Number(promoPrice) / selected.price) * 100))}%</span>}</label><label className="flex items-center gap-2 self-end text-sm"><input type="checkbox" checked={promoActive} onChange={(event) => setPromoActive(event.target.checked)} />Promoção ativa</label></div><fieldset><legend className="text-sm font-medium">Tamanhos participantes</legend><div className="mt-2 flex flex-wrap gap-2">{sizeOptions.map((size) => <button type="button" key={size} onClick={() => setSelectedSizes((current) => current.includes(size) ? current.filter((item) => item !== size) : [...current, size])} className={`rounded-lg border px-4 py-2 text-sm ${selectedSizes.includes(size) ? "border-primary bg-primary text-primary-foreground" : "border-border"}`}>{size}</button>)}</div><p className="mt-2 text-xs text-muted-foreground">Somente os tamanhos selecionados usarão o preço promocional.</p></fieldset><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : "Salvar promoção"}</button></>}</form>{loading ? <div className="rounded-xl border border-border bg-card p-8 text-sm text-muted-foreground">Carregando produtos...</div> : <>{productTable("Produtos em promoção", promotions, true)}{productTable("Produtos sem promoção", withoutPromotion, false)}</>}</div>;
}

function ProductPricesManager() {
  const [products, setProducts] = useState<AdminProduct[]>([]);
  const [productId, setProductId] = useState("");
  const [price, setPrice] = useState("");
  const [compareAtPrice, setCompareAtPrice] = useState("");
  const [variantPrices, setVariantPrices] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState("");
  async function load() { try { setLoading(true); setProducts(await listAdminProducts()); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os preços."); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []);
  const product = products.find((item) => item.id === productId);
  function selectProduct(id: string) { const item = products.find((entry) => entry.id === id); setProductId(id); setPrice(item ? String(item.price) : ""); setCompareAtPrice(item?.compare_at_price == null ? "" : String(item.compare_at_price)); setVariantPrices(Object.fromEntries((item?.product_variants ?? []).map((variant) => [variant.id, variant.price_override == null ? "" : String(variant.price_override)]))); }
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!product) return; try { setSaving(true); setError(""); await updateAdminProductPrice({ id: product.id, price: Number(price), compare_at_price: compareAtPrice ? Number(compareAtPrice) : null, variantPrices: product.product_variants.map((variant) => ({ id: variant.id, price_override: variantPrices[variant.id] ? Number(variantPrices[variant.id]) : null })) }); await load(); selectProduct(product.id); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível salvar os preços."); } finally { setSaving(false); } }
  return <div className="space-y-6"><form onSubmit={submit} className="space-y-5 rounded-xl border border-border bg-card p-5"><label className="block text-sm">Produto<select value={productId} onChange={(event) => selectProduct(event.target.value)} className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2"><option value="">Selecione</option>{products.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>{loading ? <p className="text-sm text-muted-foreground">Carregando preços...</p> : product && <><div className="grid gap-4 md:grid-cols-2"><label className="text-sm">Preço atual<input required type="number" min="0" step="0.01" value={price} onChange={(event) => setPrice(event.target.value)} className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2" /></label><label className="text-sm">Preço comparativo<input type="number" min="0" step="0.01" value={compareAtPrice} onChange={(event) => setCompareAtPrice(event.target.value)} className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2" /></label></div>{product.product_variants.length > 0 && <div className="space-y-3"><h2 className="font-medium">Preços das variantes</h2>{product.product_variants.map((variant) => <label key={variant.id} className="flex items-center justify-between gap-4 border-b border-border pb-3 text-sm"><span>{variant.sku} · {variant.size || "Sem tamanho"} · {variant.color || "Sem cor"}</span><input type="number" min="0" step="0.01" placeholder="Usa preço do produto" value={variantPrices[variant.id] ?? ""} onChange={(event) => setVariantPrices({ ...variantPrices, [variant.id]: event.target.value })} className="w-44 rounded-lg border border-input bg-background px-3 py-2" /></label>)}</div>}<button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : "Salvar alterações"}</button></>}</form>{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}</div>;
}

function ProductVariantsManager() {
  const [products, setProducts] = useState<AdminProduct[]>([]);
  const [query, setQuery] = useState("");
  const [productFilter, setProductFilter] = useState("all");
  const [colorFilter, setColorFilter] = useState("all");
  const [sizeFilter, setSizeFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [selected, setSelected] = useState<{ product: AdminProduct; variant: AdminProduct["product_variants"][number] } | null>(null);
  const [stock, setStock] = useState("");
  const [active, setActive] = useState(true);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  async function load() {
    try { setLoading(true); setError(""); setProducts(await listAdminProducts()); }
    catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar as variantes."); }
    finally { setLoading(false); }
  }
  useEffect(() => { void load(); }, []);

  const rows = products.flatMap((product) => product.product_variants.map((variant) => ({ product, variant })));
  const colors = [...new Set(rows.map(({ variant }) => variant.color).filter(Boolean))] as string[];
  const sizes = [...new Set(rows.map(({ variant }) => variant.size).filter(Boolean))] as string[];
  const filtered = rows.filter(({ product, variant }) => {
    const text = `${product.name} ${variant.sku}`.toLowerCase();
    return text.includes(query.toLowerCase()) &&
      (productFilter === "all" || product.id === productFilter) &&
      (colorFilter === "all" || variant.color === colorFilter) &&
      (sizeFilter === "all" || variant.size === sizeFilter) &&
      (statusFilter === "all" || (statusFilter === "active" ? variant.active : !variant.active));
  });
  const imageFor = (product: AdminProduct) => product.product_images.find((image) => image.is_primary) ?? product.product_images[0];
  async function saveVariant(event: React.FormEvent) { event.preventDefault(); if (!selected) return; try { setSaving(true); await updateAdminProductVariantMaintenance({ id: selected.variant.id, stock_quantity: Math.max(0, Number(stock)), active }); await load(); setSelected(null); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível salvar a variante."); } finally { setSaving(false); } }

  return <div className="space-y-6">
    {selected && <form onSubmit={saveVariant} className="space-y-4 rounded-xl border border-primary/40 bg-card p-5"><div className="flex justify-between"><div><p className="text-xs uppercase tracking-[0.2em] text-primary">Editar variante</p><h2 className="mt-2 text-xl font-semibold">{selected.product.name}</h2></div><button type="button" onClick={() => setSelected(null)} className="text-sm text-muted-foreground">Fechar</button></div><div className="grid gap-3 text-sm md:grid-cols-4"><p>Produto: {selected.product.name}</p><p>Cor: {selected.variant.color || "—"}</p><p>Tamanho: {selected.variant.size || "—"}</p><p>SKU: {selected.variant.sku}</p></div><div className="grid gap-4 md:grid-cols-2"><label className="text-sm">Estoque<input required type="number" min="0" value={stock} onChange={(event) => setStock(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="flex items-center gap-2 self-end text-sm"><input type="checkbox" checked={active} onChange={(event) => setActive(event.target.checked)} />Variante ativa</label></div><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : "Salvar alterações"}</button></form>}
    <div className="grid gap-3 rounded-xl border border-border bg-card p-4 md:grid-cols-[1fr_12rem_10rem_10rem_10rem]">
      <label className="text-sm font-medium">Pesquisar<input aria-label="Pesquisar produto ou SKU" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Produto ou SKU" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label>
      <label className="text-sm font-medium">Produto<select value={productFilter} onChange={(event) => setProductFilter(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option>{products.map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select></label>
      <label className="text-sm font-medium">Cor<select value={colorFilter} onChange={(event) => setColorFilter(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todas</option>{colors.map((color) => <option key={color} value={color}>{color}</option>)}</select></label>
      <label className="text-sm font-medium">Tamanho<select value={sizeFilter} onChange={(event) => setSizeFilter(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option>{sizes.map((size) => <option key={size} value={size}>{size}</option>)}</select></label>
      <label className="text-sm font-medium">Status<select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option><option value="active">Ativos</option><option value="inactive">Inativos</option></select></label>
    </div>
    {error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}
    <div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[760px] text-left text-sm"><thead className="border-b border-border text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Produto</th><th className="p-4">Cor</th><th className="p-4">Tamanho</th><th className="p-4">SKU</th><th className="p-4">Estoque</th><th className="p-4">Status</th></tr></thead><tbody>{loading ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Carregando variantes...</td></tr> : filtered.length === 0 ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Nenhuma variante cadastrada.</td></tr> : filtered.map(({ product, variant }) => { const image = imageFor(product); return <tr key={variant.id} tabIndex={0} role="button" onClick={() => { setSelected({ product, variant }); setStock(String(variant.stock_quantity)); setActive(variant.active); }} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { setSelected({ product, variant }); setStock(String(variant.stock_quantity)); setActive(variant.active); } }} className="cursor-pointer border-b border-border transition hover:bg-muted/50 focus-visible:bg-muted/50 last:border-0"><td className="p-4"><div className="flex items-center gap-3"><div className="h-14 w-12 overflow-hidden rounded-lg border border-border bg-muted">{image ? <img src={image.image_url} alt={image.alt_text || product.name} className="h-full w-full object-cover" /> : null}</div><span className="font-medium">{product.name}</span></div></td><td className="p-4">{variant.color || "—"}</td><td className="p-4">{variant.size || "—"}</td><td className="p-4 font-mono text-xs">{variant.sku}</td><td className="p-4">{variant.stock_quantity}</td><td className="p-4">{variant.active ? "Ativo" : "Inativo"}</td></tr>; })}</tbody></table></div>
    <p className="text-sm text-muted-foreground">{filtered.length} variante(s) encontrada(s).</p>
  </div>;
}

function ProductImagesManager() {
  const [products, setProducts] = useState<AdminProduct[]>([]);
  const [productId, setProductId] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [altText, setAltText] = useState("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  async function load() { try { setLoading(true); setProducts(await listAdminProducts()); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar as imagens."); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []);
  const product = products.find((item) => item.id === productId);
  async function addImage(event: React.FormEvent) { event.preventDefault(); if (!product || !file) return; try { setSaving(true); setError(""); await uploadAdminProductImage(product.id, file, altText || product.name, product.product_images.length, product.product_images.length === 0); setFile(null); setAltText(""); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível adicionar a imagem."); } finally { setSaving(false); } }
  async function removeImage(image: AdminProduct["product_images"][number]) { if (!window.confirm("Remover esta imagem?")) return; try { await removeAdminProductImage(image.id, image.image_url); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível remover a imagem."); } }
  return <div className="space-y-6">
    <form onSubmit={addImage} className="grid gap-4 rounded-xl border border-border bg-card p-5 md:grid-cols-[1fr_1fr_1fr_auto] md:items-end">
      <label className="text-sm">Produto<select aria-label="Produto da imagem" value={productId} onChange={(event) => setProductId(event.target.value)} className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2"><option value="">Selecione</option>{products.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
      <label className="text-sm">Arquivo<input aria-label="Arquivo da imagem" type="file" accept="image/*" onChange={(event) => setFile(event.target.files?.[0] ?? null)} className="mt-2 w-full text-sm" required /></label>
      <label className="text-sm">Texto alternativo<input aria-label="Texto alternativo" value={altText} onChange={(event) => setAltText(event.target.value)} className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2" /></label>
      <button disabled={saving || loading || !product} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Enviando..." : "Adicionar"}</button>
    </form>
    {error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}
    {!loading && products.length === 0 ? <div className="rounded-xl border border-border bg-card p-8 text-center text-muted-foreground">Nenhum produto cadastrado.</div> : <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{products.flatMap((item) => item.product_images.map((image) => <article key={image.id} className="overflow-hidden rounded-xl border border-border bg-card"><img src={image.image_url} alt={image.alt_text || item.name} className="aspect-[4/5] w-full object-cover" /><div className="space-y-2 p-4"><p className="font-medium">{item.name}</p><p className="text-xs text-muted-foreground">{image.is_primary ? "Imagem principal" : "Imagem adicional"}</p><button type="button" onClick={() => void removeImage(image)} className="text-sm text-destructive hover:underline">Remover</button></div></article>))}</div>}
  </div>;
}

function CategoriesManager() {
  const emptyForm = { name: "", description: "", active: true };
  const [categories, setCategories] = useState<AdminCategory[]>([]);
  const [form, setForm] = useState(emptyForm);
  const [editingId, setEditingId] = useState<string | undefined>();
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  async function load() {
    try { setLoading(true); setError(""); setCategories(await listAdminCategories()); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar as categorias."); } finally { setLoading(false); }
  }
  useEffect(() => { void load(); }, []);

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    if (!form.name.trim()) { setError("Informe o nome da categoria."); return; }
    try {
      setSaving(true); setError("");
      const current = editingId ? categories.find((item) => item.id === editingId) : undefined;
      const slug = (current?.slug || form.name).normalize("NFD").replace(/[\\u0300-\\u036f]/g, "").toLowerCase().trim().replace(/\\s+/g, "-").replace(/[^a-z0-9-]/g, "");
      await saveAdminCategory({ id: editingId, name: form.name.trim(), slug, description: form.description.trim() || null, image_url: current?.image_url || null, active: form.active, sort_order: current?.sort_order ?? categories.length });
      setForm(emptyForm); setEditingId(undefined); setShowForm(false); await load();
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível salvar a categoria."); } finally { setSaving(false); }
  }
  async function toggleActive(category: AdminCategory) { try { setSaving(true); setError(""); await saveAdminCategory({ ...category, active: !category.active }); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível atualizar o status."); } finally { setSaving(false); } }

  return <div className="space-y-6">
    <div className="flex justify-end"><button type="button" onClick={() => { setEditingId(undefined); setForm(emptyForm); setShowForm(true); setError(""); }} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground">Adicionar nova categoria</button></div>
    {showForm ? <form onSubmit={submit} className="grid gap-4 rounded-xl border border-border bg-card p-5 md:grid-cols-[1fr_1.5fr_auto] md:items-end">
      <label className="text-sm">Nome<input aria-label="Nome da categoria" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2" required /></label>
      <label className="text-sm">Descrição<input aria-label="Descrição da categoria" value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2" /></label>
      <div className="flex items-center gap-3"><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={form.active} onChange={(event) => setForm({ ...form, active: event.target.checked })} />Ativa</label><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : editingId ? "Atualizar" : "Criar"}</button><button type="button" onClick={() => { setShowForm(false); setEditingId(undefined); setForm(emptyForm); }} className="rounded-lg border border-border px-4 py-2 text-sm">Cancelar</button></div>
    </form> : null}
    {error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}
    <div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full text-left text-sm"><thead className="border-b border-border text-muted-foreground"><tr><th className="p-4">Nome</th><th className="p-4">Produtos vinculados</th><th className="p-4">Status</th><th className="p-4">Ações</th></tr></thead><tbody>{loading ? <tr><td colSpan={4} className="p-8 text-center text-muted-foreground">Carregando categorias...</td></tr> : categories.length === 0 ? <tr><td colSpan={4} className="p-8 text-center text-muted-foreground">Nenhuma categoria cadastrada.</td></tr> : categories.map((category) => <tr key={category.id} className="border-b border-border last:border-0"><td className="p-4 font-medium">{category.name}</td><td className="p-4 text-muted-foreground">{category.product_count ?? 0}</td><td className="p-4">{category.active ? "Ativa" : "Inativa"}</td><td className="p-4"><button type="button" onClick={() => { setEditingId(category.id); setShowForm(true); setForm({ name: category.name, description: category.description || "", active: category.active }); setError(""); }} className="mr-3 text-primary hover:underline">Editar</button><button type="button" onClick={() => void toggleActive(category)} className="text-primary hover:underline">{category.active ? "Desativar" : "Ativar"}</button></td></tr>)}</tbody></table></div>
  </div>;
}
